INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010000","revision":1,"targetId":"80000000-0000-4000-8000-000000000100","prompt":"Für das ___ der Supportanfragen, bis kein Fall mehr offen ist, ist heute ein eigenes Team zuständig.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"Look for the noun describing the step-by-step completion of a backlog.","de":"Gesucht ist das Nomen für das schrittweise Erledigen eines Rückstands."},"options":[{"id":"0","text":"Abarbeiten"},{"id":"1","text":"Ausdrucken"},{"id":"2","text":"Archivieren"},{"id":"3","text":"Verteilen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Das Abarbeiten refers to working through a series of outstanding tasks; it is a nominalized infinitive with das.","de":"Das Abarbeiten bezeichnet das schrittweise Erledigen offener Aufgaben; der substantivierte Infinitiv steht mit das."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für das Abarbeiten der Supportanfragen, bis kein Fall mehr offen ist, ist heute ein eigenes Team zuständig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L1 (6a89e3256dedb8de6c86fb3d4a6ab110afe55f77b0c43e3c19240f13dc368925). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
