INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010060','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010060","revision":1,"targetId":"80000000-0000-4000-8000-000000000106","prompt":"Im Aufhebungsvertrag wurde eine einmalige ___ für das Ausscheiden vereinbart.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"A one-off payment may be agreed when a job ends.","de":"Bei der Beendigung eines Arbeitsverhältnisses kann eine einmalige Zahlung vereinbart werden."},"options":[{"id":"0","text":"Abmahnung"},{"id":"1","text":"Lohnabrechnung"},{"id":"2","text":"Abfindung"},{"id":"3","text":"Befristung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"An Abfindung is a severance payment. It does not arise automatically whenever employment ends.","de":"Eine Abfindung ist eine Ausgleichszahlung bei der Beendigung eines Arbeitsverhältnisses. Sie entsteht nicht in jedem Fall automatisch."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Aufhebungsvertrag wurde eine einmalige Abfindung für das Ausscheiden vereinbart.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L9 (bb4b1ca8fbf62cb718e7a47c799c8bf81d95896e665d9b15846349bc95a105d3). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
