INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010061','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010061","revision":1,"targetId":"80000000-0000-4000-8000-000000000106","prompt":"Nach Verhandlungen bot die Firma dem Mitarbeiter eine ___ für die vorzeitige Vertragsauflösung an.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"A one-off payment may be agreed when a job ends.","de":"Bei der Beendigung eines Arbeitsverhältnisses kann eine einmalige Zahlung vereinbart werden."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Gehaltsabrechnung"},{"id":"1","text":"Vertragsverlängerung"},{"id":"2","text":"Probezeit"},{"id":"3","text":"Abfindung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"An Abfindung is a severance payment. It does not arise automatically whenever employment ends.","de":"Eine Abfindung ist eine Ausgleichszahlung bei der Beendigung eines Arbeitsverhältnisses. Sie entsteht nicht in jedem Fall automatisch."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach Verhandlungen bot die Firma dem Mitarbeiter eine Abfindung für die vorzeitige Vertragsauflösung an.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L9 (bb4b1ca8fbf62cb718e7a47c799c8bf81d95896e665d9b15846349bc95a105d3). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner