INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010070","revision":1,"targetId":"80000000-0000-4000-8000-000000000107","prompt":"Im Sozialplan wurde eine Abfindung für den Verlust des Arbeitsplatzes vereinbart. Die Beschäftigten prüfen, wann sie einen ___ haben.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"This describes a claim to a payment, not the money already received.","de":"Gemeint ist das Recht auf eine Zahlung, nicht die bereits erhaltene Zahlung."},"options":[{"id":"0","text":"Urlaubsanspruch"},{"id":"1","text":"Abfindungsanspruch"},{"id":"2","text":"Auskunftsanspruch"},{"id":"3","text":"Rückzahlungsanspruch"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Abfindungsanspruch means an entitlement to severance, which must have a valid basis.","de":"Ein Abfindungsanspruch ist ein rechtlich begründeter Anspruch auf eine Abfindung; er besteht nicht bei jeder Kündigung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Sozialplan wurde eine Abfindung für den Verlust des Arbeitsplatzes vereinbart. Die Beschäftigten prüfen, wann sie einen Abfindungsanspruch haben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L10 (7770b172c48d0b64da25a04da94e03b1bd5ed2d7337319fdc54eb04644af3acd). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
