INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010140','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010140","revision":1,"targetId":"80000000-0000-4000-8000-000000000114","prompt":"Wegen wiederholter Verstöße gegen Sicherheitsregeln erhielt der Angestellte eine schriftliche ___.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"The message formally objects to a breach and warns against repeating it.","de":"Es handelt sich um eine förmliche Beanstandung eines Pflicht- oder Vertragsverstoßes."},"options":[{"id":"0","text":"Gehaltsabrechnung"},{"id":"1","text":"Versetzung"},{"id":"2","text":"Abmahnung"},{"id":"3","text":"Abfindung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"An Abmahnung is a formal warning in an employment or contractual context, not just casual advice.","de":"Eine Abmahnung ist eine förmliche Rüge wegen eines Pflicht- oder Vertragsverstoßes, nicht bloß ein informeller Hinweis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen wiederholter Verstöße gegen Sicherheitsregeln erhielt der Angestellte eine schriftliche Abmahnung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L18 (123d2d3bf340b3b1ac1f4f1e4f79c97fc42254b92512c15aad67209863a98203). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
