INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010141','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010141","revision":1,"targetId":"80000000-0000-4000-8000-000000000114","prompt":"Der Vermieter wollte den Mietvertrag fortsetzen, beanstandete aber schriftlich die Verstöße und verlangte künftig vertragsgemäßes Verhalten. Er schickte eine förmliche ___.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"The message formally objects to a breach and warns against repeating it.","de":"Es handelt sich um eine förmliche Beanstandung eines Pflicht- oder Vertragsverstoßes."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Kündigung"},{"id":"1","text":"Mietabrechnung"},{"id":"2","text":"Einladung"},{"id":"3","text":"Abmahnung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"An Abmahnung is a formal warning in an employment or contractual context, not just casual advice.","de":"Eine Abmahnung ist eine förmliche Rüge wegen eines Pflicht- oder Vertragsverstoßes, nicht bloß ein informeller Hinweis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Vermieter wollte den Mietvertrag fortsetzen, beanstandete aber schriftlich die Verstöße und verlangte künftig vertragsgemäßes Verhalten. Er schickte eine förmliche Abmahnung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L18 (123d2d3bf340b3b1ac1f4f1e4f79c97fc42254b92512c15aad67209863a98203). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic rel