INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000010180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000010180","revision":1,"targetId":"80000000-0000-4000-8000-000000000118","prompt":"Auf der monatlichen ___ stehen Lohn, Zuschläge und Abzüge getrennt.","instruction":{"en":"Select the noun that best completes the sentence.","de":"Wähle das Nomen, das den Satz am besten ergänzt."},"hint":{"en":"Look for a document breaking down individual charges, hours or deductions.","de":"Gesucht ist eine Aufstellung einzelner Beträge, Stunden oder Abzüge."},"options":[{"id":"0","text":"Gehaltsvereinbarung"},{"id":"1","text":"Arbeitsanweisung"},{"id":"2","text":"Abrechnung"},{"id":"3","text":"Dienstplanung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Abrechnung refers to an itemized statement or settlement, for example of wages or treatment costs.","de":"Eine Abrechnung stellt Beträge und ihre Berechnung nachvollziehbar dar, etwa beim Lohn oder bei Behandlungskosten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf der monatlichen Abrechnung stehen Lohn, Zuschläge und Abzüge getrennt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 wording, 2026-10-28; lemma and lexical facts from pinned GM2 source apps/web/data/pos/nouns.jsonl:L22 (561b9068565a1424fc1c8d7ea69a3900251b7467b9fd6d632d7e3d3c30b10872). Legacy flags and examples are unverified; no source examples copied. No external dataset or publication rights certification. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
