INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050000","revision":1,"targetId":"80000000-0000-4000-8000-000000000500","prompt":"Ich kontrolliere die Adresse, ___ ich das Paket verschicke.","instruction":{"en":"Express the order of events, rather than a condition.","de":"Drücke die zeitliche Reihenfolge aus, keine Bedingung."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"options":[{"id":"0","text":"bevor"},{"id":"1","text":"obwohl"},{"id":"2","text":"sodass"},{"id":"3","text":"falls"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Use bevor to link an earlier action to a subsequent action.","de":"Bevor leitet den Nebensatz mit der späteren Handlung ein; der Hauptsatz beschreibt etwas, das vorher geschieht."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich kontrolliere die Adresse, bevor ich das Paket verschicke.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L5 (556edeee94cf20e240a5894a4110250093b6f51b49115809add2fb782e0ac5ff); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
