INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050010","revision":1,"targetId":"80000000-0000-4000-8000-000000000501","prompt":"Lena stellt einen Wecker, ___ sie den frühen Zug nicht verpasst.","instruction":{"en":"Choose the connector or expression that conveys the intended logical relationship.","de":"Wähle die Konjunktion oder Wendung, die den gemeinten Zusammenhang ausdrückt."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"options":[{"id":"0","text":"obwohl"},{"id":"1","text":"damit"},{"id":"2","text":"nachdem"},{"id":"3","text":"indem"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Use damit to express the intended purpose of an action, with a subordinate clause.","de":"Damit verbindet eine Handlung mit der Absicht, ein Ziel zu erreichen; im Nebensatz steht das Verb am Ende."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Lena stellt einen Wecker, damit sie den frühen Zug nicht verpasst.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L7 (7427692aab8b6f497a5a39b7dae143512fa910f7060a99b4cc3347018961b26c); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
