INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050011","revision":1,"targetId":"80000000-0000-4000-8000-000000000501","prompt":"Der Betrieb erklärt die Sicherheitsregeln mehrfach, ___ alle Beschäftigten sie verstehen.","instruction":{"en":"Express the company’s intended purpose, rather than the order of events.","de":"Drücke die Absicht des Betriebs aus, keine zeitliche Reihenfolge."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"slots":[{"id":"connector","label":"Konnektor","options":[{"id":"0","text":"obgleich"},{"id":"1","text":"bevor"},{"id":"2","text":"damit"},{"id":"3","text":"falls"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"connector","optionId":"2"}]}],"explanation":{"en":"Use damit to express the intended purpose of an action, with a subordinate clause.","de":"Damit verbindet eine Handlung mit der Absicht, ein Ziel zu erreichen; im Nebensatz steht das Verb am Ende."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Betrieb erklärt die Sicherheitsregeln mehrfach, damit alle Beschäftigten sie verstehen.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L7 (7427692aab8b6f497a5a39b7dae143512fa910f7060a99b4cc3347018961b26c); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production auth