INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050080","revision":1,"targetId":"80000000-0000-4000-8000-000000000508","prompt":"Die Firma senkt den Stromverbrauch, ___ sie nachts nicht benötigte Geräte ausschaltet.","instruction":{"en":"Express the means by which the company reduces electricity use.","de":"Drücke das Mittel aus, durch das die Firma den Stromverbrauch senkt."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"options":[{"id":"0","text":"indem"},{"id":"1","text":"obwohl"},{"id":"2","text":"bevor"},{"id":"3","text":"falls"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Use indem to explain the means by which an outcome is achieved.","de":"Indem beschreibt, auf welche Weise ein Ergebnis erreicht wird."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma senkt den Stromverbrauch, indem sie nachts nicht benötigte Geräte ausschaltet.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L17 (e4e7ffedb77669288c4daed81d257688f2e27ce38d26a81da74185bf0b171612); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
