INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050111','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050111","revision":1,"targetId":"80000000-0000-4000-8000-000000000511","prompt":"Die Gäste verließen den Saal, ___ die letzte Rede zu Ende gewesen war.","instruction":{"en":"Choose the connector or expression that conveys the intended logical relationship.","de":"Wähle die Konjunktion oder Wendung, die den gemeinten Zusammenhang ausdrückt."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"slots":[{"id":"connector","label":"Konnektor","options":[{"id":"0","text":"nachdem"},{"id":"1","text":"obwohl"},{"id":"2","text":"damit"},{"id":"3","text":"falls"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"connector","optionId":"0"}]}],"explanation":{"en":"Use nachdem to introduce an earlier completed event before the main action.","de":"Nachdem leitet ein Ereignis ein, das vor der Handlung des Hauptsatzes abgeschlossen ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Gäste verließen den Saal, nachdem die letzte Rede zu Ende gewesen war.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L20 (e69810ad56cedb259f1a014988a67ee98b391fc03523db71318f8458874f99f4); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects ex