INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050140','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050140","revision":1,"targetId":"80000000-0000-4000-8000-000000000514","prompt":"___ der Zug zwanzig Minuten Verspätung hatte, kam Lea rechtzeitig zum Bewerbungsgespräch.","instruction":{"en":"Express a contrast with the expected consequence of the delay.","de":"Drücke einen Gegensatz zur erwarteten Folge der Verspätung aus."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"options":[{"id":"0","text":"Weil"},{"id":"1","text":"Nachdem"},{"id":"2","text":"Obwohl"},{"id":"3","text":"Damit"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Use obwohl to mark a circumstance that would normally argue against the stated result.","de":"Obwohl leitet einen Umstand ein, der dem Ergebnis normalerweise entgegensteht."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl der Zug zwanzig Minuten Verspätung hatte, kam Lea rechtzeitig zum Bewerbungsgespräch.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L23 (756b60a294e7974d7dc7c54805abf25e8c161e55af842c0737a3809216503605); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
