INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050150","revision":1,"targetId":"80000000-0000-4000-8000-000000000515","prompt":"Die Straße war so stark vereist, ___ die Busse nicht mehr fahren konnten.","instruction":{"en":"Choose the connector or expression that conveys the intended logical relationship.","de":"Wähle die Konjunktion oder Wendung, die den gemeinten Zusammenhang ausdrückt."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"options":[{"id":"0","text":"obwohl"},{"id":"1","text":"bevor"},{"id":"2","text":"falls"},{"id":"3","text":"so dass"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Use so dass to introduce the consequence of a situation; sodass is an equally valid spelling.","de":"So dass leitet die Folge eines Sachverhalts ein; die Zusammenschreibung sodass ist ebenso korrekt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Straße war so stark vereist, so dass die Busse nicht mehr fahren konnten.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L25 (3af14b41b99a0e59311c6c2ce84146e98660cf205a894a6dd0fc40decad716f6); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
