INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000050151','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000050151","revision":1,"targetId":"80000000-0000-4000-8000-000000000515","prompt":"Der Wind wurde immer heftiger, ___ mehrere Bäume umstürzten.","instruction":{"en":"Express the consequence of the stronger wind, rather than events happening at the same time.","de":"Drücke die Folge des stärkeren Windes aus, keine bloße Gleichzeitigkeit."},"hint":{"en":"Identify whether the sentences express time, condition, consequence, purpose, contrast or manner.","de":"Prüfe, ob die Sätze Zeit, Bedingung, Folge, Absicht, Gegensatz oder Art und Weise ausdrücken."},"slots":[{"id":"connector","label":"Konnektor","options":[{"id":"0","text":"so dass"},{"id":"1","text":"indem"},{"id":"2","text":"während"},{"id":"3","text":"falls"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"connector","optionId":"0"}]}],"explanation":{"en":"Use so dass to introduce the consequence of a situation; sodass is an equally valid spelling.","de":"So dass leitet die Folge eines Sachverhalts ein; die Zusammenschreibung sodass ist ebenso korrekt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Wind wurde immer heftiger, so dass mehrere Bäume umstürzten.","emphasis":false}]}}','de-nfc-trim-v1','Original bilingual GPT-6 content 2026-10-28, lemma seeded by apps/web/data/pos/conjunctions.jsonl:L25 (3af14b41b99a0e59311c6c2ce84146e98660cf205a894a6dd0fc40decad716f6); no inherited examples copied or external APIs. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved mater