INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000070011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000070011","revision":1,"targetId":"80000000-0000-4000-8000-000000000701","prompt":"Der Techniker hat den Schritt schon gezeigt, aber ich habe ihn vergessen. Bitte zeigen Sie ihn mir ___.","instruction":{"en":"Choose the expression requesting one more repetition.","de":"Wähle den Ausdruck, mit dem man um eine Wiederholung bittet."},"hint":{"en":"The action has happened already and the speaker asks to hear or see it again.","de":"Die Handlung fand schon statt. Die Person bittet um eine Wiederholung."},"slots":[{"id":"expression","label":"Ausdruck","options":[{"id":"0","text":"zum ersten Mal"},{"id":"1","text":"nie wieder"},{"id":"2","text":"noch mal"},{"id":"3","text":"überhaupt nicht"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"2"}]}],"explanation":{"en":"Noch mal means ''one more time''. The spelling nochmal is also accepted.","de":"Noch mal bedeutet „noch einmal“. Auch die Schreibweise nochmal ist korrekt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Techniker hat den Schritt schon gezeigt, aber ich habe ihn vergessen. Bitte zeigen Sie ihn mir noch mal.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based only on pinned lemma apps/web/data/pos/particles.jsonl:L5 (50c28a380b11547d60242c3d3072a292efdfcf7294fc90beb6187543cac30add), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
