INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000080000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000080000","revision":1,"targetId":"80000000-0000-4000-8000-000000000800","prompt":"Die Firma hat nicht mehr Geld eingenommen, aber 300 zusätzliche Geräte verkauft. Der ___ ist gestiegen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Look for the number of items sold rather than the money earned.","de":"Achte auf die verkaufte Stückzahl, nicht auf den Geldbetrag."},"options":[{"id":"0","text":"Umsatz"},{"id":"1","text":"Absatz"},{"id":"2","text":"Gewinn"},{"id":"3","text":"Preis"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Absatz describes how many units are sold; Umsatz is monetary turnover.","de":"Absatz bezeichnet die verkaufte Menge; Umsatz bezeichnet den Geldwert der Verkäufe."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma hat nicht mehr Geld eingenommen, aber 300 zusätzliche Geräte verkauft. Der Absatz ist gestiegen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/nouns.jsonl:L24 (4a9d7afffb44d33be8ed4c7b228627fea7c30431faeae2d3f5bced59ed7bfb0f), 2026-10-28. Legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
