INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000080010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000080010","revision":1,"targetId":"80000000-0000-4000-8000-000000000801","prompt":"Als Mira in eine andere Stadt zog, kamen ihre Freunde zum ___ an den Bahnhof.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone is leaving and other people mark the parting.","de":"Eine Person geht weg; die anderen verabschieden sich."},"options":[{"id":"0","text":"Empfang"},{"id":"1","text":"Besuch"},{"id":"2","text":"Abschied"},{"id":"3","text":"Beginn"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Abschied names the act or occasion of saying goodbye.","de":"Abschied bezeichnet das Verabschieden oder den Moment des Auseinandergehens."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Als Mira in eine andere Stadt zog, kamen ihre Freunde zum Abschied an den Bahnhof.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/nouns.jsonl:L25 (59fdb2edf0fb67aadbb6ef6fed1e2f0bd577bc042608ccc055673746ef9c3e91), 2026-10-28. Legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
