INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000080020','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000080020","revision":1,"targetId":"80000000-0000-4000-8000-000000000802","prompt":"Nach der bestandenen Prüfung erhielt Jonas seinen beruflichen ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The context mentions completing education and receiving a qualification.","de":"Es geht um eine abgeschlossene Ausbildung oder ein Studium."},"options":[{"id":"0","text":"Vertrag"},{"id":"1","text":"Ausweis"},{"id":"2","text":"Antrag"},{"id":"3","text":"Abschluss"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"An Abschluss can be a qualification awarded after study or vocational training; it does not mean exclusion.","de":"Ein Abschluss kann ein Bildungs- oder Berufsabschluss sein; Ausschluss ist ein anderes Wort."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der bestandenen Prüfung erhielt Jonas seinen beruflichen Abschluss.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/nouns.jsonl:L26 (949dfedd492c20378f3387410bce4338ce05f4bb762d70e35d5b2fe8219d6f91), 2026-10-28. Legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
