INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000080030','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000080030","revision":1,"targetId":"80000000-0000-4000-8000-000000000803","prompt":"Der Bericht besteht aus vier großen Teilen mit eigenen Überschriften. Jeder ___ behandelt ein anderes Thema.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The text is divided into larger units, often with headings.","de":"Der Text ist in größere Teile mit Überschriften gegliedert."},"options":[{"id":"0","text":"Absatz"},{"id":"1","text":"Satz"},{"id":"2","text":"Abschnitt"},{"id":"3","text":"Begriff"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"An Abschnitt is a section; an Absatz is normally a paragraph within a section.","de":"Ein Abschnitt ist ein größerer Textteil; ein Absatz ist meist ein Teil davon."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Bericht besteht aus vier großen Teilen mit eigenen Überschriften. Jeder Abschnitt behandelt ein anderes Thema.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/nouns.jsonl:L27 (6a2a2b5f88a689b5859d009e4623b0188588a14d78fbcef413fa6a2ed86764a2), 2026-10-28. Legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
