INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000080180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000080180","revision":1,"targetId":"80000000-0000-4000-8000-000000000818","prompt":"Als Rauch in der Küche aufstieg, löste der Melder einen ___ aus.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A warning is triggered because there may be danger.","de":"Ein Warnsignal wird wegen einer möglichen Gefahr ausgelöst."},"options":[{"id":"0","text":"Auftrag"},{"id":"1","text":"Alarm"},{"id":"2","text":"Antrag"},{"id":"3","text":"Bericht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Alarm is a warning signal or alert; it is not a report or request.","de":"Alarm ist ein Warnsignal oder eine Warnmeldung, kein Bericht oder Antrag."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Als Rauch in der Küche aufstieg, löste der Melder einen Alarm aus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/nouns.jsonl:L46 (6b134d2819bc6a4f672a7dac8dbc6df98daa8508028278614b20a96f12569e8a), 2026-10-28. Legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
