INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000090010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000090010","revision":1,"targetId":"80000000-0000-4000-8000-000000000901","prompt":"Das Konzert fällt ersatzlos aus. Der Veranstalter muss es ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The event will not take place and no replacement date is arranged.","de":"Die Veranstaltung findet nicht statt; ein neuer Termin ist nicht vorgesehen."},"options":[{"id":"0","text":"verschieben"},{"id":"1","text":"ankündigen"},{"id":"2","text":"verlängern"},{"id":"3","text":"absagen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Absagen cancels a planned event; verschieben moves it to another date.","de":"Absagen bedeutet, dass ein Termin entfällt; verschieben bedeutet, ihn zu verlegen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Konzert fällt ersatzlos aus. Der Veranstalter muss es absagen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts based on pinned source apps/web/data/pos/verbs.jsonl:L26 (8e5a00ab9dcc4be939eb85f5421411d0fa0c280a81348964455fc5650f322f41), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
