INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100001','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100001","revision":1,"targetId":"80000000-0000-4000-8000-000000001000","prompt":"Die Bestellung steht im System noch auf „offen“. ___ wurde sie noch nicht verschickt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The speaker infers something from clues but cannot confirm it.","de":"Aus Hinweisen wird etwas vermutet, ohne dass es sicher feststeht."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Ausführlich"},{"id":"1","text":"Anschließend"},{"id":"2","text":"Anscheinend"},{"id":"3","text":"Pünktlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Anscheinend expresses an appearance-based inference, not a confirmed fact.","de":"Anscheinend drückt eine Vermutung aufgrund von Anzeichen aus, keine Gewissheit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Bestellung steht im System noch auf „offen“. Anscheinend wurde sie noch nicht verschickt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L24 (ff06700cc65852ccdc145a83f661e39a8b9d68262555f0aca032394306e89604), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
