INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100011","revision":1,"targetId":"80000000-0000-4000-8000-000000001001","prompt":"Der Kurs endet um 16 Uhr. Erst danach beginnt die Fragerunde. ___ können die Teilnehmenden Fragen stellen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"One event finishes before the next begins.","de":"Eine Handlung endet, bevor die nächste beginnt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Anderswo"},{"id":"1","text":"Anschließend"},{"id":"2","text":"Vorher"},{"id":"3","text":"Stattdessen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Anschließend means afterward or subsequently, marking sequence.","de":"Anschließend bedeutet danach und kennzeichnet die zeitliche Reihenfolge."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Kurs endet um 16 Uhr. Erst danach beginnt die Fragerunde. Anschließend können die Teilnehmenden Fragen stellen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L25 (5eec368ff1971c425fefd85b6b19ef61551921a2509c7dc3a8ee54506d7ad7d8), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
