INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100021','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100021","revision":1,"targetId":"80000000-0000-4000-8000-000000001002","prompt":"Der Patient darf noch keinen Besuch empfangen; die Infektion ist weiterhin ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The concern is that other people may catch the infection.","de":"Die Sorge ist, dass sich andere Menschen infizieren können."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"ansteckend"},{"id":"1","text":"ausgeheilt"},{"id":"2","text":"schmerzfrei"},{"id":"3","text":"unauffällig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"Ansteckend means contagious, not merely painful or long-lasting.","de":"Ansteckend bedeutet übertragbar, nicht einfach schmerzhaft oder langwierig."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Patient darf noch keinen Besuch empfangen; die Infektion ist weiterhin ansteckend.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L26 (da7b626e399442e3d9b77d797dde31c7326fd708d4639884a9f4babc3af21852), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
