INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100031','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100031","revision":1,"targetId":"80000000-0000-4000-8000-000000001003","prompt":"Die Lehrerin ruft die Namen auf und markiert, wer im Raum ___ ist.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The question is who is actually there, not merely registered.","de":"Es geht darum, wer wirklich vor Ort ist, nicht nur angemeldet."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"angemeldet"},{"id":"1","text":"verspätet"},{"id":"2","text":"abgemeldet"},{"id":"3","text":"anwesend"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Anwesend means present; abwesend means absent.","de":"Anwesend bedeutet vor Ort; abwesend bedeutet nicht da."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Lehrerin ruft die Namen auf und markiert, wer im Raum anwesend ist.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L27 (2a52bb4a8972e656e3a72602ced7a5f01b83decded098b6aed00f09879de1fc1), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
