INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100040","revision":1,"targetId":"80000000-0000-4000-8000-000000001004","prompt":"Nach der Genesung kann er seine Aufgaben wieder ohne Einschränkung erledigen. Er ist ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person can carry out the required tasks.","de":"Die Person kann ihre beruflichen Aufgaben ausführen."},"options":[{"id":"0","text":"arbeitsfähig"},{"id":"1","text":"arbeitslos"},{"id":"2","text":"arbeitsunfähig"},{"id":"3","text":"arbeitssuchend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Arbeitsfähig describes ability to work; it is not the same as being employed.","de":"Arbeitsfähig heißt, arbeiten zu können; es sagt nichts darüber, ob man eine Stelle hat."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Genesung kann er seine Aufgaben wieder ohne Einschränkung erledigen. Er ist arbeitsfähig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L28 (8ff51a402cce459822d3e72289713f16862256f664ae4a93a0f3e35cfebfa219), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
