INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100051','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100051","revision":1,"targetId":"80000000-0000-4000-8000-000000001005","prompt":"Sie hat gerade ihr Studium beendet und bewirbt sich bei mehreren Firmen. Sie ist ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person is applying for positions and wants to find work.","de":"Die Person bewirbt sich und sucht eine Stelle."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"pensioniert"},{"id":"1","text":"arbeitssuchend"},{"id":"2","text":"angestellt"},{"id":"3","text":"beurlaubt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Arbeitssuchend means seeking employment; it is not synonymous with being unable to work.","de":"Arbeitssuchend bedeutet, eine Stelle zu suchen, nicht arbeitsunfähig zu sein."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie hat gerade ihr Studium beendet und bewirbt sich bei mehreren Firmen. Sie ist arbeitssuchend.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L30 (0d1d1df93070dc5f10c2b4db8db16176540ddff0d29af8b59b29ab710528d05e), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
