INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100060','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100060","revision":1,"targetId":"80000000-0000-4000-8000-000000001006","prompt":"Wegen des gebrochenen Arms kann der Mechaniker vorübergehend nicht arbeiten. Er ist ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"An illness or injury prevents the person from working.","de":"Eine Erkrankung oder Verletzung verhindert die Arbeit."},"options":[{"id":"0","text":"arbeitssuchend"},{"id":"1","text":"arbeitsfähig"},{"id":"2","text":"arbeitsunfähig"},{"id":"3","text":"arbeitslos"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Arbeitsunfähig means unfit for work, which differs from being unemployed.","de":"Arbeitsunfähig bedeutet, krankheitsbedingt nicht arbeiten zu können; das ist nicht arbeitslos."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen des gebrochenen Arms kann der Mechaniker vorübergehend nicht arbeiten. Er ist arbeitsunfähig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L31 (a8c3d332b0ee3cd18f2b9277af2e383ccca79e49c4a8c8c4b2cf6cc8e933356d), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
