INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100070","revision":1,"targetId":"80000000-0000-4000-8000-000000001007","prompt":"Die Kündigungsfrist steht ausdrücklich im Arbeitsvertrag. Sie ist ___ geregelt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The rule is contained in the signed employment agreement.","de":"Die Regel steht im unterschriebenen Arbeitsvertrag."},"options":[{"id":"0","text":"freiwillig"},{"id":"1","text":"arbeitsvertraglich"},{"id":"2","text":"mündlich"},{"id":"3","text":"zufällig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Arbeitsvertraglich means defined or agreed in an employment contract.","de":"Arbeitsvertraglich bedeutet, im Arbeitsvertrag geregelt oder vereinbart."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kündigungsfrist steht ausdrücklich im Arbeitsvertrag. Sie ist arbeitsvertraglich geregelt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L32 (db87ad9bef8a1ae75dd7c0e19d137cf650af0e3589dabd82e95310242e397af6), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
