INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100080","revision":1,"targetId":"80000000-0000-4000-8000-000000001008","prompt":"Der Zug fährt zehn Minuten vor der geplanten Zeit ab. Das ist wirklich ___ für die Wartenden.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Something unwanted causes irritation or frustration.","de":"Etwas Unerwünschtes sorgt für Verärgerung."},"options":[{"id":"0","text":"ärgerlich"},{"id":"1","text":"angenehm"},{"id":"2","text":"hilfreich"},{"id":"3","text":"pünktlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Ärgerlich describes something annoying or regrettable in context.","de":"Ärgerlich beschreibt hier etwas, das stört oder frustriert."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Zug fährt zehn Minuten vor der geplanten Zeit ab. Das ist wirklich ärgerlich für die Wartenden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L33 (a572f6274f83b66730007a8613b4a6446f0d1c2b78beea8fa44bcf229a857073), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
