INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100091","revision":1,"targetId":"80000000-0000-4000-8000-000000001009","prompt":"Die Stadt hat neue Parks und günstige Wohnungen gebaut und ist für Familien ___ geworden.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The offer or place has features that people value.","de":"Das Angebot oder der Ort hat Eigenschaften, die Menschen ansprechen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"unbekannt"},{"id":"1","text":"attraktiv"},{"id":"2","text":"unbewohnbar"},{"id":"3","text":"gefährlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Attraktiv means appealing or desirable, not necessarily physically beautiful.","de":"Attraktiv bedeutet ansprechend oder vorteilhaft, nicht nur äußerlich schön."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Stadt hat neue Parks und günstige Wohnungen gebaut und ist für Familien attraktiv geworden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L35 (55ca0b91cf6cb635a688bb8313d3328d2172056cdc3b3cb011fcfd92b3af864a), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
