INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100100","revision":1,"targetId":"80000000-0000-4000-8000-000000001010","prompt":"Der Verkäufer lässt die Kundin nicht in Ruhe und spricht sie immer wieder an. Sie findet ihn ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone keeps pressing despite signs that attention is unwanted.","de":"Jemand drängt sich auf, obwohl das nicht erwünscht ist."},"options":[{"id":"0","text":"höflich"},{"id":"1","text":"geduldig"},{"id":"2","text":"aufdringlich"},{"id":"3","text":"zurückhaltend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Aufdringlich means pushy or intrusive, unlike reserved or considerate behavior.","de":"Aufdringlich bedeutet sich aufdrängend, im Gegensatz zu zurückhaltend."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Verkäufer lässt die Kundin nicht in Ruhe und spricht sie immer wieder an. Sie findet ihn aufdringlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L36 (5a975cfb33ea774b6119a22ce388bbce34f1aa5b23869ee7d36700065264f9fd), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
