INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100110","revision":1,"targetId":"80000000-0000-4000-8000-000000001011","prompt":"Der Schüler hört genau zu und bemerkt sogar kleine Fehler. Er ist sehr ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"One person notices details; another notices what someone needs.","de":"Eine Person achtet auf Details, eine andere auf die Bedürfnisse von Menschen."},"options":[{"id":"0","text":"müde"},{"id":"1","text":"aufmerksam"},{"id":"2","text":"abgelenkt"},{"id":"3","text":"unbeteiligt"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Aufmerksam can mean alert and observant, or considerate toward someone.","de":"Aufmerksam kann aufmerksam beobachtend oder rücksichtsvoll und zugewandt bedeuten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Schüler hört genau zu und bemerkt sogar kleine Fehler. Er ist sehr aufmerksam.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L37 (35a85d65e697c4a74b0ef77349c4003d60bd0af4e3aaffb29066b71341e9c2e3), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
