INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100121","revision":1,"targetId":"80000000-0000-4000-8000-000000001012","prompt":"In der Einladung wird die Anmeldepflicht unmissverständlich hervorgehoben. Dort steht ___, dass eine Anmeldung erforderlich ist.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A requirement is stated unmistakably rather than merely implied.","de":"Eine Vorgabe wird eindeutig genannt und nicht nur angedeutet."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"vermutlich"},{"id":"1","text":"nebenbei"},{"id":"2","text":"ausdrücklich"},{"id":"3","text":"heimlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Ausdrücklich means expressly or explicitly, not silently or by chance.","de":"Ausdrücklich bedeutet klar und ausdrücklich gesagt, nicht stillschweigend."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In der Einladung wird die Anmeldepflicht unmissverständlich hervorgehoben. Dort steht ausdrücklich, dass eine Anmeldung erforderlich ist.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L38 (e4a147ec273b37b4f60ad731fd06e3b0a71cdb679c77ff5e979df1dca3affe38), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
