INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100131','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100131","revision":1,"targetId":"80000000-0000-4000-8000-000000001013","prompt":"Sie beantwortet die Frage nicht mit einem Satz, sondern erklärt alle Hintergründe ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The explanation covers many steps and supporting details.","de":"Die Erklärung enthält viele Schritte und zusätzliche Einzelheiten."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"widersprüchlich"},{"id":"1","text":"ausführlich"},{"id":"2","text":"kurz"},{"id":"3","text":"beiläufig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Ausführlich means detailed or thorough, unlike knapp or oberflächlich.","de":"Ausführlich bedeutet detailliert und gründlich, anders als knapp oder oberflächlich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie beantwortet die Frage nicht mit einem Satz, sondern erklärt alle Hintergründe ausführlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L39 (626340d0ebf2f53089f01285c7fc9a8bd2e49a63afe948437bba4a75618d33c1), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
