INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100160','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100160","revision":1,"targetId":"80000000-0000-4000-8000-000000001016","prompt":"Die Firma sucht offiziell Bewerber. Die Stelle ist seit Montag ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"One context is a published vacancy; the other is a full written form.","de":"Einmal geht es um eine veröffentlichte Stelle, einmal um ein ausgeschriebenes Wort."},"options":[{"id":"0","text":"ausgeschrieben"},{"id":"1","text":"ausgestattet"},{"id":"2","text":"abgesichert"},{"id":"3","text":"abgeschlossen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"A job can be ausgeschrieben (advertised); a word can be ausgeschrieben (written out in full).","de":"Eine Stelle kann ausgeschrieben sein; ebenso kann ein Wort vollständig ausgeschrieben werden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma sucht offiziell Bewerber. Die Stelle ist seit Montag ausgeschrieben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L42 (c0bea33e67d824a1ca05098c37a309ad8215f0c5f95e461214f44aa5e271e470), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
