INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100171','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100171","revision":1,"targetId":"80000000-0000-4000-8000-000000001017","prompt":"Jedes Gästezimmer hat WLAN und einen Schreibtisch. Die Zimmer sind entsprechend ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The room or workplace has the items needed for its purpose.","de":"Der Raum oder Arbeitsplatz verfügt über die nötige Ausstattung."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"ansteckend"},{"id":"1","text":"ausgestattet"},{"id":"2","text":"abgeschlossen"},{"id":"3","text":"angemessen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Ausgestattet means furnished or equipped with appropriate resources.","de":"Ausgestattet bedeutet mit Geräten, Möbeln oder anderen Mitteln versehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Jedes Gästezimmer hat WLAN und einen Schreibtisch. Die Zimmer sind entsprechend ausgestattet.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L43 (70cc2f44fcaac2740c00dd671e971b1ce81b0a0deddc63f1c6f3b83c0fbfda4f), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
