INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100180","revision":1,"targetId":"80000000-0000-4000-8000-000000001018","prompt":"Die Grafik zeigt klare Unterschiede zwischen den Gruppen. Sie ist besonders ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The data or presentation supports an interpretation clearly.","de":"Die Daten oder die Darstellung erlauben eine klare Aussage."},"options":[{"id":"0","text":"unvollständig"},{"id":"1","text":"zufällig"},{"id":"2","text":"aussagekräftig"},{"id":"3","text":"unleserlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Aussagekräftig means informative and meaningful enough to support a judgment.","de":"Aussagekräftig bedeutet, dass Informationen eine begründete Aussage ermöglichen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Grafik zeigt klare Unterschiede zwischen den Gruppen. Sie ist besonders aussagekräftig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L45 (9dba95f50452cb64d2da267535f40bcf407418fcec9a6d2f1c3b6100d708011a), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
