INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000100191','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000100191","revision":1,"targetId":"80000000-0000-4000-8000-000000001019","prompt":"Das Team verlor knapp; ein Fehler in der letzten Minute war ___ für die Niederlage.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"One factor makes the difference between possible outcomes.","de":"Ein bestimmter Faktor entscheidet über das Ergebnis."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"harmlos"},{"id":"1","text":"unbeteiligt"},{"id":"2","text":"unverbindlich"},{"id":"3","text":"ausschlaggebend"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Ausschlaggebend means decisive, not merely relevant or incidental.","de":"Ausschlaggebend bedeutet entscheidend, nicht nur nebensächlich beteiligt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Team verlor knapp; ein Fehler in der letzten Minute war ausschlaggebend für die Niederlage.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adjectives.jsonl:L46 (b8aca957531383047dc70b377e108fbe8cf830638aa2b2fd43ea29cb7185a8c2), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
