INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000110000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000110000","revision":1,"targetId":"80000000-0000-4000-8000-000000001100","prompt":"Das Gerät ist nicht kaputt, ___ nur ausgeschaltet.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The first option is denied and replaced by the correct one.","de":"Die erste Möglichkeit wird verneint und durch die richtige ersetzt."},"options":[{"id":"0","text":"sondern"},{"id":"1","text":"obwohl"},{"id":"2","text":"weil"},{"id":"3","text":"damit"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"After nicht or kein, sondern introduces the replacement, not just an additional contrast.","de":"Nach nicht oder kein nennt sondern die richtige Alternative."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Gerät ist nicht kaputt, sondern nur ausgeschaltet.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences from pinned source apps/web/data/pos/conjunctions.jsonl:L30 (647d905834e62f449bd2f791fca170e3b9092b6bdc25a407cb612918e8840919), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
