INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000110010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000110010","revision":1,"targetId":"80000000-0000-4000-8000-000000001101","prompt":"___ ich weiß, beginnt die Sitzung um zehn Uhr; ich bin mir aber nicht sicher.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The speaker reports incomplete information rather than a confirmed fact.","de":"Die Person gibt Wissen oder Gehörtes unter Vorbehalt wieder."},"options":[{"id":"0","text":"Sobald"},{"id":"1","text":"Obwohl"},{"id":"2","text":"Damit"},{"id":"3","text":"Soviel"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Soviel ich weiß means ''as far as I know''; soweit ich weiß is also standard and often preferred.","de":"Soviel ich weiß bedeutet „soweit ich weiß“; auch soweit ich weiß ist üblich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Soviel ich weiß, beginnt die Sitzung um zehn Uhr; ich bin mir aber nicht sicher.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences from pinned source apps/web/data/pos/conjunctions.jsonl:L31 (14ee13e562a96ceb0d86aee8236333d2ff0cca6a7e039345398c13e1d55978d9), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
