INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000110060','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000110060","revision":1,"targetId":"80000000-0000-4000-8000-000000001106","prompt":"Die Wohnung ist ___ klein, aber sehr hell.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The first statement is admitted, but the second limits its importance.","de":"Der erste Sachverhalt wird eingeräumt, der zweite setzt einen Gegensatz."},"options":[{"id":"0","text":"sobald"},{"id":"1","text":"obwohl"},{"id":"2","text":"zwar"},{"id":"3","text":"weder"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Zwar introduces a concession that is commonly followed by aber or doch.","de":"Zwar räumt etwas ein; danach folgt häufig ein Gegensatz mit aber oder doch."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Wohnung ist zwar klein, aber sehr hell.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences from pinned source apps/web/data/pos/conjunctions.jsonl:L39 (07eaf800e95357f63761ba8c1fcbd045bc1d75a86424aa73da39c90556e637cf), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
