INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120020','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120020","revision":1,"targetId":"80000000-0000-4000-8000-000000001202","prompt":"Die Unterlagen sind ___ angekommen; du musst sie nicht noch einmal schicken.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The action was completed earlier than the current moment.","de":"Die Handlung ist zum jetzigen Zeitpunkt schon geschehen."},"options":[{"id":"0","text":"bereits"},{"id":"1","text":"bald"},{"id":"2","text":"später"},{"id":"3","text":"niemals"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Bereits means already, not later or never.","de":"Bereits bedeutet schon, nicht später oder niemals."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Unterlagen sind bereits angekommen; du musst sie nicht noch einmal schicken.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L28 (222544c9aeec8d8f053b24426b457a919890a291ab604753c90957b822b7c73a), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
