INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120031','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120031","revision":1,"targetId":"80000000-0000-4000-8000-000000001203","prompt":"Die Suche läuft noch. ___ gibt es keine Ergebnisse.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The statement covers the time until now, and more may happen later.","de":"Die Aussage gilt bis jetzt; später kann sich noch etwas ändern."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Künftig"},{"id":"1","text":"Bisher"},{"id":"2","text":"Danach"},{"id":"3","text":"Gestern"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Bisher means so far or until now.","de":"Bisher bedeutet bis jetzt oder bislang."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Suche läuft noch. Bisher gibt es keine Ergebnisse.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L30 (f2cde7641507a9fb762597493df077e538467bf673bbe4db270adbdfe0ebfbd9), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
