INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120040","revision":1,"targetId":"80000000-0000-4000-8000-000000001204","prompt":"Ich finde den Betrag viel zu klein und betone die geringe Menge: Ich habe ___ fünf Euro dabei.","instruction":{"en":"Choose the word meaning only a limited amount, rather than a minimum or an extra amount.","de":"Wähle das Wort für nur eine geringe Menge, nicht für eine Mindestmenge oder eine zusätzliche Menge."},"hint":{"en":"The speaker emphasizes that the amount or affected part is limited.","de":"Es wird betont, dass nur eine kleine Menge oder ein Teil gemeint ist."},"options":[{"id":"0","text":"zusätzlich"},{"id":"1","text":"mindestens"},{"id":"2","text":"bloß"},{"id":"3","text":"sogar"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Bloß can mean only or merely; nur can also be used in many such contexts.","de":"Bloß kann nur oder lediglich bedeuten; oft ist auch nur möglich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich finde den Betrag viel zu klein und betone die geringe Menge: Ich habe bloß fünf Euro dabei.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L32 (c8174095a8a93785e202b903da96f5178d234c841389265949508bfbcac16da5), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
