INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120051','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120051","revision":1,"targetId":"80000000-0000-4000-8000-000000001205","prompt":"Auf der Rechnung wird der Preis ___ ausgewiesen; die Mehrwertsteuer ist schon enthalten.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The amount is before deductions or includes VAT.","de":"Der Betrag ist vor Abzügen oder enthält die Mehrwertsteuer."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"netto"},{"id":"1","text":"steuerfrei"},{"id":"2","text":"unverbindlich"},{"id":"3","text":"brutto"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Brutto is before payroll deductions or including VAT; netto is the corresponding net amount.","de":"Brutto bedeutet vor Lohnabzügen oder inklusive Mehrwertsteuer; netto bezeichnet den Nettobetrag."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf der Rechnung wird der Preis brutto ausgewiesen; die Mehrwertsteuer ist schon enthalten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L33 (7f3671d8adb889039ded7f8d9e7cac060225dc7115ee6bc3c06637ab9c37af5a), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
