INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120060','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120060","revision":1,"targetId":"80000000-0000-4000-8000-000000001206","prompt":"Es regnete stark. ___ fand das Konzert im Freien statt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The second event happens despite what the first statement suggests.","de":"Das zweite Ereignis tritt trotz eines Hindernisses ein."},"options":[{"id":"0","text":"Dennoch"},{"id":"1","text":"Deshalb"},{"id":"2","text":"Darum"},{"id":"3","text":"Folglich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Dennoch means nevertheless, expressing a concession.","de":"Dennoch bedeutet trotzdem und drückt einen Gegensatz zur Erwartung aus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Es regnete stark. Dennoch fand das Konzert im Freien statt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L38 (efcc1689a3fa438dd1b382f33e772cd3a3c42741014b9b1061ca35595f81c7e5), 2026-10-28; legacy examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
