INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120070","revision":1,"targetId":"80000000-0000-4000-8000-000000001207","prompt":"Letzte Woche fiel das Treffen aus. ___ findet es wie geplant statt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Earlier attempts or occasions were different.","de":"Frühere Versuche oder Gelegenheiten verliefen anders."},"options":[{"id":"0","text":"Diesmal"},{"id":"1","text":"Damals"},{"id":"2","text":"Früher"},{"id":"3","text":"Niemals"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Diesmal means on this occasion, often contrasted with a previous one.","de":"Diesmal bedeutet bei dieser Gelegenheit, oft im Gegensatz zu früher."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Letzte Woche fiel das Treffen aus. Diesmal findet es wie geplant statt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L39 (d03bafcf5aec55c811e14f026b1f4b1d371685f6748f1aa693693d74793c43b3), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
