INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120071','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120071","revision":1,"targetId":"80000000-0000-4000-8000-000000001207","prompt":"Bei den letzten beiden Versuchen war der Code falsch. Der gerade abgeschlossene aktuelle Versuch war erfolgreich: ___ hat die Anmeldung funktioniert.","instruction":{"en":"Choose the expression referring specifically to this current attempt.","de":"Wähle den Ausdruck für diesen konkreten aktuellen Versuch."},"hint":{"en":"Earlier attempts or occasions were different.","de":"Frühere Versuche oder Gelegenheiten verliefen anders."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Bisher"},{"id":"1","text":"Später"},{"id":"2","text":"Diesmal"},{"id":"3","text":"Damals"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Diesmal means on this occasion, often contrasted with a previous one.","de":"Diesmal bedeutet bei dieser Gelegenheit, oft im Gegensatz zu früher."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Bei den letzten beiden Versuchen war der Code falsch. Der gerade abgeschlossene aktuelle Versuch war erfolgreich: Diesmal hat die Anmeldung funktioniert.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L39 (d03bafcf5aec55c811e14f026b1f4b1d371685f6748f1aa693693d74793c43b3), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
