INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120101","revision":1,"targetId":"80000000-0000-4000-8000-000000001210","prompt":"Die Termine wurden falsch eingetragen, und niemand weiß mehr, was wann stattfindet. Der Plan ist völlig ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The order has been lost and things are confused.","de":"Die Ordnung ist verloren gegangen und alles ist vermischt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"pünktlich"},{"id":"1","text":"durcheinander"},{"id":"2","text":"übersichtlich"},{"id":"3","text":"verbindlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Durcheinander describes a confused or disorderly state.","de":"Durcheinander beschreibt einen ungeordneten oder verwirrten Zustand."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Termine wurden falsch eingetragen, und niemand weiß mehr, was wann stattfindet. Der Plan ist völlig durcheinander.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L47 (e54a29bd2725d301b1a20c503be16725acc6fb93dfdb8a1f5e4a6ae3594caf40), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
