INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120120","revision":1,"targetId":"80000000-0000-4000-8000-000000001212","prompt":"Der neue Vertrag ist ___ wichtig wie der alte.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Two things are equally important or done in the same way.","de":"Zwei Dinge sind gleich wichtig oder werden auf gleiche Weise getan."},"options":[{"id":"0","text":"bisher"},{"id":"1","text":"damals"},{"id":"2","text":"ebenso"},{"id":"3","text":"trotzdem"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Ebenso means equally or in the same way; ebenso ... wie expresses equal degree.","de":"Ebenso bedeutet genauso; ebenso ... wie drückt den gleichen Grad aus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Vertrag ist ebenso wichtig wie der alte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L49 (7df380b54f85dbbf8786fcd1c356d1bb1d80cdec90b1a6c8aa5f579fbf378a60), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
