INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000120130','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000120130","revision":1,"targetId":"80000000-0000-4000-8000-000000001213","prompt":"___ möchte sie umziehen, andererseits gefällt ihr die Nachbarschaft.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Two opposing considerations are being weighed.","de":"Zwei gegensätzliche Gesichtspunkte werden einander gegenübergestellt."},"options":[{"id":"0","text":"Sobald"},{"id":"1","text":"Einerseits"},{"id":"2","text":"Deshalb"},{"id":"3","text":"Trotzdem"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Einerseits introduces one consideration; andererseits presents the other.","de":"Einerseits nennt die eine Seite; andererseits stellt die andere gegenüber."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Einerseits möchte sie umziehen, andererseits gefällt ihr die Nachbarschaft.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 sentences based on pinned source apps/web/data/pos/adverbs.jsonl:L51 (b0ef3ca339c485870f6da884b288673e44ab9aacedfe7b83359d7e385451de68), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
