INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000130190','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000130190","revision":1,"targetId":"80000000-0000-4000-8000-000000001319","prompt":"Die Figuren werden im Film nicht von echten Schauspielern dargestellt, sondern durch digitale ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Pictures or graphics are made to appear to move.","de":"Bilder oder Grafiken werden so gestaltet, dass sie sich bewegen."},"options":[{"id":"0","text":"Animation"},{"id":"1","text":"Analyse"},{"id":"2","text":"Anfahrt"},{"id":"3","text":"Abrechnung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"An Animation is a sequence of images or graphics creating apparent motion.","de":"Eine Animation ist eine Bildfolge oder Grafik, die Bewegung darstellt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Figuren werden im Film nicht von echten Schauspielern dargestellt, sondern durch digitale Animation.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L72 (dd9d9d0a04e2597016a09887e589f49cc6dfe89d202a67b802255f16e033dd5f), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
