INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000140001','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000140001","revision":1,"targetId":"80000000-0000-4000-8000-000000001400","prompt":"Die Therapie kann ohne dieses Medikament nicht fortgesetzt werden. Der Patient ist darauf ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone cannot manage without a necessary resource or support.","de":"Eine Person oder Einrichtung benötigt eine bestimmte Hilfe oder Ressource und kann nicht ohne sie auskommen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"eingestellt"},{"id":"1","text":"neugierig"},{"id":"2","text":"angewiesen"},{"id":"3","text":"vorbereitet"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Angewiesen auf expresses essential dependence; auf takes the accusative here.","de":"Angewiesen auf drückt notwendige Abhängigkeit aus; auf steht hier mit Akkusativ."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Therapie kann ohne dieses Medikament nicht fortgesetzt werden. Der Patient ist darauf angewiesen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L49 (8a5b7436bc6a7e427afe5d46a8b80673ecb8bea3cbaeb10359ae41f483914765), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
