INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000140031','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000140031","revision":1,"targetId":"80000000-0000-4000-8000-000000001403","prompt":"Die Journalistin prüft die Betonung in einer reinen Tonaufnahme. Dafür möchte sie das Interview noch einmal ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Listen attentively to understand a person''s account or a recording.","de":"Man hört aufmerksam zu, um eine Darstellung oder Aufnahme zu verstehen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"ausdrucken"},{"id":"1","text":"anhören"},{"id":"2","text":"abschreiben"},{"id":"3","text":"ansehen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Sich etwas anhören means listening attentively to an account or an audio recording.","de":"Sich etwas anhören bedeutet, einer Darstellung oder Tonaufnahme aufmerksam zuzuhören."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Journalistin prüft die Betonung in einer reinen Tonaufnahme. Dafür möchte sie das Interview noch einmal anhören.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L52 (ae6690fb41c23cefc1adb5c3d871e92dbae2dc1e2375fac1d85ac57946ae90c1), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
