INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000140040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000140040","revision":1,"targetId":"80000000-0000-4000-8000-000000001404","prompt":"Das Stadtmuseum will Eigentümer der historischen Karte werden und den Kaufpreis bezahlen. Es möchte die Karte für seine Sammlung ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"An institution or trader acquires an item by paying for it.","de":"Eine Einrichtung oder ein Händler erwirbt etwas gegen Bezahlung."},"options":[{"id":"0","text":"ausleihen"},{"id":"1","text":"ankaufen"},{"id":"2","text":"zurückgeben"},{"id":"3","text":"verschenken"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Ankaufen means acquiring something for payment, often in trade or for a collection.","de":"Ankaufen bezeichnet den Erwerb gegen Bezahlung, oft im Handel oder für eine Sammlung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Stadtmuseum will Eigentümer der historischen Karte werden und den Kaufpreis bezahlen. Es möchte die Karte für seine Sammlung ankaufen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L53 (93aef8262902a17bb7ec0394c9e1321edb2c41e5758ac2ad83f65ae0b0440ce9), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
