INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150000","revision":1,"targetId":"80000000-0000-4000-8000-000000001500","prompt":"Der Karton ist ___ unbeschädigt, aber der Inhalt ist zerbrochen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Focus on what is visible from the outside rather than inside.","de":"Es geht um die von außen sichtbare Seite, nicht um den inneren Zustand."},"options":[{"id":"0","text":"inhaltlich"},{"id":"1","text":"äußerlich"},{"id":"2","text":"zeitlich"},{"id":"3","text":"rechtlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Äußerlich refers to external appearance rather than internal condition.","de":"Äußerlich bezieht sich auf das äußere Erscheinungsbild, nicht auf den inneren Zustand."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Karton ist äußerlich unbeschädigt, aber der Inhalt ist zerbrochen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L47 (55090216a7fbe26cea260966b34b074d6149e6262febd8e00808854b193ddeeb), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
