INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150010","revision":1,"targetId":"80000000-0000-4000-8000-000000001501","prompt":"Die Leistung lag weit über dem Durchschnitt; die Jury bezeichnete sie als ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A quality or performance is far beyond the usual level.","de":"Eine Eigenschaft oder Leistung liegt deutlich über dem Üblichen."},"options":[{"id":"0","text":"durchschnittlich"},{"id":"1","text":"üblich"},{"id":"2","text":"außerordentlich"},{"id":"3","text":"zufällig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Außerordentlich can express unusually high intensity or exceptional quality.","de":"Außerordentlich kann eine ungewöhnlich hohe Intensität oder besondere Qualität ausdrücken."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Leistung lag weit über dem Durchschnitt; die Jury bezeichnete sie als außerordentlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L48 (5ed53ed6c3c1ce37e3993ea000cc963e2fcb9366f7092ae700fea956af94a385), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
