INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150011","revision":1,"targetId":"80000000-0000-4000-8000-000000001501","prompt":"Die Zusammenarbeit verlief ___ gut; selbst schwierige Aufgaben waren schneller als geplant erledigt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A quality or performance is far beyond the usual level.","de":"Eine Eigenschaft oder Leistung liegt deutlich über dem Üblichen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"mäßig"},{"id":"1","text":"außerordentlich"},{"id":"2","text":"kaum"},{"id":"3","text":"wenig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Außerordentlich can express unusually high intensity or exceptional quality.","de":"Außerordentlich kann eine ungewöhnlich hohe Intensität oder besondere Qualität ausdrücken."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Zusammenarbeit verlief außerordentlich gut; selbst schwierige Aufgaben waren schneller als geplant erledigt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L48 (5ed53ed6c3c1ce37e3993ea000cc963e2fcb9366f7092ae700fea956af94a385), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
