INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150020','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150020","revision":1,"targetId":"80000000-0000-4000-8000-000000001502","prompt":"Die Veranstalter entschuldigen sich: Dass die Ausstellung heute schließen muss, ist ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"An unwanted event causes regret or disappointment.","de":"Ein unerwünschtes Ereignis ruft Enttäuschung oder Bedauern hervor."},"options":[{"id":"0","text":"erfreulich"},{"id":"1","text":"wünschenswert"},{"id":"2","text":"bedauerlich"},{"id":"3","text":"erfolgreich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Bedauerlich describes something regretted because of its unwelcome consequences.","de":"Bedauerlich beschreibt etwas, das man wegen seiner unerwünschten Folgen bedauert."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Veranstalter entschuldigen sich: Dass die Ausstellung heute schließen muss, ist bedauerlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L51 (b5208d6720b332db47cd7cb714b66e20d9688c105260720cea8b8f4a264c2a20), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
