INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150030','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150030","revision":1,"targetId":"80000000-0000-4000-8000-000000001503","prompt":"Nach Monaten der Ungewissheit war die klare Entscheidung für sie ___; endlich konnte sie wieder ruhig schlafen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Relief and freedom are felt after pressure or uncertainty.","de":"Nach Druck oder Unsicherheit fühlt man sich erleichtert und freier."},"options":[{"id":"0","text":"ermüdend"},{"id":"1","text":"befreiend"},{"id":"2","text":"beängstigend"},{"id":"3","text":"belastend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Befreiend describes relief when a burden or pressure is lifted.","de":"Befreiend bezeichnet ein Gefühl der Erleichterung, wenn eine Belastung nachlässt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach Monaten der Ungewissheit war die klare Entscheidung für sie befreiend; endlich konnte sie wieder ruhig schlafen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L52 (1e434ddee49b7c33b3858bea6361bc9a7072421b31f5098ea9ee404b322be42b), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
