INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150161','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150161","revision":1,"targetId":"80000000-0000-4000-8000-000000001516","prompt":"Die Forscherin erklärt die Vererbung der Augenfarbe aus ___ Sicht, nicht aus wirtschaftlicher.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A process or explanation concerns living organisms or biology.","de":"Ein Zusammenhang betrifft Lebewesen, Zellen oder biologische Vorgänge."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"rechtlicher"},{"id":"1","text":"biologischer"},{"id":"2","text":"wirtschaftlicher"},{"id":"3","text":"historischer"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Biologisch relates to living organisms and their processes; here it is not a food label.","de":"Biologisch bezieht sich auf Lebewesen und ihre Vorgänge; hier ist nicht das Bio-Lebensmittelsiegel gemeint."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Forscherin erklärt die Vererbung der Augenfarbe aus biologischer Sicht, nicht aus wirtschaftlicher.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L67 (dd7e36f6f996aef79e19096e4402999e4ac9f3f0ed0fb68a69b02b2081c39fd3), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
