INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150170","revision":1,"targetId":"80000000-0000-4000-8000-000000001517","prompt":"Nach zehn Jahren im Amt gibt die ___ Leiterin morgen die Verantwortung an ihren Nachfolger ab.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Refer to someone or results existing up to the present change.","de":"Es geht um eine Person oder Ergebnisse aus der Zeit bis zum jetzigen Wechsel."},"options":[{"id":"0","text":"künftige"},{"id":"1","text":"neue"},{"id":"2","text":"bisherige"},{"id":"3","text":"kommende"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Bisherig is used attributively for something that existed or applied up to now.","de":"Bisherig steht attributiv und bezeichnet etwas, das bis zum jetzigen Zeitpunkt galt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach zehn Jahren im Amt gibt die bisherige Leiterin morgen die Verantwortung an ihren Nachfolger ab.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L68 (a478ea29f61510008cedc8b5db22948281674c24a2b7f41764d58f5b3aba1ca7), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
