INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150171','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150171","revision":1,"targetId":"80000000-0000-4000-8000-000000001517","prompt":"Die ersten drei Tests sind bereits abgeschlossen. Wir vergleichen die ___ Ergebnisse dieser Tests mit den Messungen aus der nächsten Testphase.","instruction":{"en":"Choose the adjective for results already available up to now, rather than predictions.","de":"Wähle das Adjektiv für Ergebnisse, die bis jetzt vorliegen, nicht für Vorhersagen."},"hint":{"en":"Refer to someone or results existing up to the present change.","de":"Es geht um eine Person oder Ergebnisse aus der Zeit bis zum jetzigen Wechsel."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"künftigen"},{"id":"1","text":"bisherigen"},{"id":"2","text":"geplanten"},{"id":"3","text":"erwarteten"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Bisherig is used attributively for something that existed or applied up to now.","de":"Bisherig steht attributiv und bezeichnet etwas, das bis zum jetzigen Zeitpunkt galt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die ersten drei Tests sind bereits abgeschlossen. Wir vergleichen die bisherigen Ergebnisse dieser Tests mit den Messungen aus der nächsten Testphase.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L68 (a478ea29f61510008cedc8b5db22948281674c24a2b7f41764d58f5b3aba1ca7), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially ap