INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150180","revision":1,"targetId":"80000000-0000-4000-8000-000000001518","prompt":"Nach der Blutabnahme wurde ihm schwindelig, und er war plötzlich sehr ___ im Gesicht.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone looks unusually pale, for example when feeling unwell.","de":"Eine Person hat auffallend wenig Farbe im Gesicht, etwa bei Unwohlsein."},"options":[{"id":"0","text":"sonnig"},{"id":"1","text":"blass"},{"id":"2","text":"laut"},{"id":"3","text":"gebräunt"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Blass describes a face with little color or an unusually pale complexion.","de":"Blass bedeutet, dass das Gesicht wenig Farbe zeigt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Blutabnahme wurde ihm schwindelig, und er war plötzlich sehr blass im Gesicht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L70 (3960aa1379e576833d8cbbdc6363804a3d3fd7aef283498dfeb7582a9c3efc5c), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
