INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000150191','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000150191","revision":1,"targetId":"80000000-0000-4000-8000-000000001519","prompt":"Die Ampel gibt ein akustisches Signal, damit auch ___ Fußgänger den Übergang finden können.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A person cannot see and may use accessible alternatives to visual information.","de":"Eine Person kann nicht sehen und nutzt gegebenenfalls andere Zugänge zu Informationen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"eilige"},{"id":"1","text":"blinde"},{"id":"2","text":"junge"},{"id":"3","text":"müde"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Blind refers to lack of sight; Braille and audio signals can support access and orientation.","de":"Blind bezeichnet fehlendes Sehvermögen; Brailleschrift und akustische Signale können Orientierung unterstützen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Ampel gibt ein akustisches Signal, damit auch blinde Fußgänger den Übergang finden können.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L72 (37e667d9d55dbe3c3e59eaf74b5ce70e3f490f80fb8c9431afc07e1c630e8684), 2026-10-28; source examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
