INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000160000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000160000","revision":1,"targetId":"80000000-0000-4000-8000-000000001600","prompt":"Obwohl alle zuhörten, hat niemand auch nur ein Wort verstanden. Sie haben ___ nichts verstanden.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Gar intensifies a negative statement to mean none or not at all.","de":"Mit gar wird eine Verneinung besonders stark und vollständig ausgedrückt."},"options":[{"id":"0","text":"fast"},{"id":"1","text":"gar"},{"id":"2","text":"kaum"},{"id":"3","text":"sogar"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Gar strengthens a negation, as in gar nichts or gar keine.","de":"Gar verstärkt die Verneinung, etwa in gar nichts oder gar keine."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl alle zuhörten, hat niemand auch nur ein Wort verstanden. Sie haben gar nichts verstanden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L62 (cf891153141921ef647715b31c9ed02782d82cf966e52007695c8b3e00fea82f), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
