INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000160040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000160040","revision":1,"targetId":"80000000-0000-4000-8000-000000001604","prompt":"Sie arbeitet jeden Vormittag vier Stunden und hat nachmittags frei. Sie ist ___ beschäftigt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Work or care takes place for only part of the day, roughly half a day.","de":"Arbeit oder Betreuung findet nur während eines halben Tages statt."},"options":[{"id":"0","text":"ganztags"},{"id":"1","text":"nachts"},{"id":"2","text":"halbtags"},{"id":"3","text":"ständig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Halbtags means that an activity covers only about half a day.","de":"Halbtags bedeutet, dass eine Tätigkeit nur einen halben Tag umfasst."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie arbeitet jeden Vormittag vier Stunden und hat nachmittags frei. Sie ist halbtags beschäftigt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L75 (8db72aefd8f5afbdc421b83c4f25027b984338374999a44c163f2af7916f85f6), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
