INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000160080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000160080","revision":1,"targetId":"80000000-0000-4000-8000-000000001608","prompt":"Eine Journalistin schreibt aus Deutschland über die Regeln in Deutschland: „___ gilt diese Vorschrift.“","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The expression refers to the country where the speaker is located.","de":"Der Ausdruck bezieht sich auf das Land, in dem die sprechende Person sich befindet."},"options":[{"id":"0","text":"Weltweit"},{"id":"1","text":"Anderswo"},{"id":"2","text":"Hierzulande"},{"id":"3","text":"Überall"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Hierzulande means in this country from the speaker''s perspective.","de":"Hierzulande meint in diesem Land aus der Sicht der sprechenden Person."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Eine Journalistin schreibt aus Deutschland über die Regeln in Deutschland: „Hierzulande gilt diese Vorschrift.“","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L85 (c48ade6653d2bc22385988451b685032f5052bd1e35494258ad9eeb0b8394158), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
