INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000160110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000160110","revision":1,"targetId":"80000000-0000-4000-8000-000000001611","prompt":"Von außen ist das Haus alt, aber ___ wurde alles neu gestrichen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Something is on the inner side rather than the outer side.","de":"Etwas befindet sich auf der inneren, nicht der äußeren Seite."},"options":[{"id":"0","text":"draußen"},{"id":"1","text":"innen"},{"id":"2","text":"oben"},{"id":"3","text":"nebenan"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Innen indicates an inner area or inner surface.","de":"Innen bezeichnet den inneren Bereich oder die Innenseite."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Von außen ist das Haus alt, aber innen wurde alles neu gestrichen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L92 (bdb749e3bd70337c584107b9053dfc73a458612bfedb45a44ca2c3c8ece9dd80), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
