INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170020','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170020","revision":1,"targetId":"80000000-0000-4000-8000-000000001702","prompt":"Der neue Drucker funktioniert nicht sofort. Lies zuerst die ___ mit den einzelnen Schritten.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Which document tells someone how to proceed step by step?","de":"Welches Dokument erklärt ein Vorgehen Schritt für Schritt?"},"options":[{"id":"0","text":"Anleitung"},{"id":"1","text":"Rechnung"},{"id":"2","text":"Garantie"},{"id":"3","text":"Werbung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Anleitung is a set of instructions or a manual, not a receipt or warranty.","de":"Eine Anleitung beschreibt Arbeitsschritte; sie ist keine Rechnung oder Garantie."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Drucker funktioniert nicht sofort. Lies zuerst die Anleitung mit den einzelnen Schritten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L76 (b60a70b418fb2ff4cd3402d131b2044bda9136e1d538e30be90b459afd4c5bb7), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
