INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170030','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170030","revision":1,"targetId":"80000000-0000-4000-8000-000000001703","prompt":"Im Bürgerbüro fragt die Mitarbeiterin: „Was ist Ihr ___?“ Der Besucher möchte seine Adresse ändern lassen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person is explaining what they need help with.","de":"Die Person erklärt, wobei sie Unterstützung möchte."},"options":[{"id":"0","text":"Ausweis"},{"id":"1","text":"Anliegen"},{"id":"2","text":"Wohnort"},{"id":"3","text":"Termin"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Anliegen refers to a person''s concern or request in this context.","de":"Anliegen bezeichnet hier die Bitte oder das vorgebrachte Anliegen einer Person."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Bürgerbüro fragt die Mitarbeiterin: „Was ist Ihr Anliegen?“ Der Besucher möchte seine Adresse ändern lassen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L77 (fbd0a08a31b2786232f68fd4f59b513c11dfdd4647fb43c5b21dfa3dc86bfd45), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
