INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170051','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170051","revision":1,"targetId":"80000000-0000-4000-8000-000000001705","prompt":"Auf ___ der Feuerwehr wurde das Gebäude sofort geräumt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The instruction is mandatory, not a suggestion.","de":"Die Vorgabe ist verbindlich und nicht bloß ein Vorschlag."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Anfrage"},{"id":"1","text":"Angebot"},{"id":"2","text":"Anordnung"},{"id":"3","text":"Erinnerung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Anordnung expresses a binding directive in these situations.","de":"Anordnung bezeichnet hier eine verbindliche Weisung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf Anordnung der Feuerwehr wurde das Gebäude sofort geräumt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L80 (4d1b70d00d6b7f837131a6aebfe55cf7955727c86f65428cdee9bc521bd4369a), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
