INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170060','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170060","revision":1,"targetId":"80000000-0000-4000-8000-000000001706","prompt":"Der Vertrag garantiert Beschäftigten nach einem Jahr einen zusätzlichen Urlaubstag. Sie haben darauf ein ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A rule or contract guarantees this benefit.","de":"Eine Regel oder ein Vertrag sichert die Leistung zu."},"options":[{"id":"0","text":"Interesse"},{"id":"1","text":"Anrecht"},{"id":"2","text":"Bedürfnis"},{"id":"3","text":"Angebot"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Anrecht auf is an entitlement, stronger than an interest or wish.","de":"Anrecht auf bezeichnet einen Anspruch, nicht nur einen Wunsch oder ein Interesse."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Vertrag garantiert Beschäftigten nach einem Jahr einen zusätzlichen Urlaubstag. Sie haben darauf ein Anrecht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L81 (e3850c1c2de61fc1a6f3a01ae1e12bb545525677aebc945575a69d57779a7a96), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
