INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170070","revision":1,"targetId":"80000000-0000-4000-8000-000000001707","prompt":"Am Telefon meldete sich ein Mann, nannte aber keinen Namen. Die Mitarbeiterin notierte: „___ unbekannt“.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Who initiated the telephone conversation?","de":"Wer hat das Telefongespräch begonnen?"},"options":[{"id":"0","text":"Empfänger"},{"id":"1","text":"Anrufer"},{"id":"2","text":"Absender"},{"id":"3","text":"Besucher"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Anrufer means caller; Empfänger or Absender describe different roles.","de":"Anrufer bezeichnet denjenigen, der anruft, nicht den Empfänger."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Am Telefon meldete sich ein Mann, nannte aber keinen Namen. Die Mitarbeiterin notierte: „Anrufer unbekannt“.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L85 (ee23825b18967697b1f8487f5157c51adf4da7ab215212e56008fd8dd7b6ed87), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
