INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170100","revision":1,"targetId":"80000000-0000-4000-8000-000000001710","prompt":"Für die Bewerbung schickt Ela ihren Lebenslauf und einen Brief, in dem sie ihre Motivation erklärt. Dieser Brief ist das ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Which application document explains why the person wants the position?","de":"Welches Bewerbungsdokument erläutert die Motivation für die Stelle?"},"options":[{"id":"0","text":"Zeugnis"},{"id":"1","text":"Anschreiben"},{"id":"2","text":"Protokoll"},{"id":"3","text":"Formular"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"The Anschreiben is the application cover letter, not the CV or certificate.","de":"Das Anschreiben ist der Bewerbungsbrief, nicht der Lebenslauf oder ein Zeugnis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Bewerbung schickt Ela ihren Lebenslauf und einen Brief, in dem sie ihre Motivation erklärt. Dieser Brief ist das Anschreiben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L90 (5995cd7b11cd71c44f2d9b01dab6d515d3a3e9664be0210772dcde001e558b7b), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
