INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170150","revision":1,"targetId":"80000000-0000-4000-8000-000000001715","prompt":"Nach fünf Stunden Bergsteigen waren alle erschöpft. Der Aufstieg war eine große ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The activity took considerable energy and work.","de":"Die Tätigkeit erforderte viel Kraft und Einsatz."},"options":[{"id":"0","text":"Erleichterung"},{"id":"1","text":"Anstrengung"},{"id":"2","text":"Erholung"},{"id":"3","text":"Abkürzung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Anstrengung is effort or exertion, rather than rest or relief.","de":"Anstrengung bezeichnet körperliche oder geistige Mühe."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach fünf Stunden Bergsteigen waren alle erschöpft. Der Aufstieg war eine große Anstrengung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L95 (456cafcb4b406d66f51e7a33231111a712b8a73158a9307f3f1d1b7f57fc0a81), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
