INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180050','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180050","revision":1,"targetId":"80000000-0000-4000-8000-000000001805","prompt":"Alle Berichte haben dieselbe Schriftart. Nur der letzte ist knallrot und ___ sofort auf.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Something is unusually noticeable compared with the others.","de":"Etwas wird wegen eines Unterschieds besonders bemerkt."},"options":[{"id":"0","text":"stellt"},{"id":"1","text":"hört"},{"id":"2","text":"fällt"},{"id":"3","text":"hält"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Auffallen means to stand out; the perfect tense uses ist aufgefallen.","de":"Auffallen heißt, bemerkt zu werden; das Perfekt lautet ist aufgefallen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Alle Berichte haben dieselbe Schriftart. Nur der letzte ist knallrot und fällt sofort auf.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L86 (1e6034c0538b87310f0a8de0c8a7978de824daed7616a30dd0fc011ff8c62ddd), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
