INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180080","revision":1,"targetId":"80000000-0000-4000-8000-000000001808","prompt":"Nach zehn Versuchen gelang die Reparatur immer noch nicht. Trotzdem wollte Nina nicht ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person stops or considers stopping an effort.","de":"Eine Person beendet oder erwägt, ihre Bemühungen zu beenden."},"options":[{"id":"0","text":"aufheben"},{"id":"1","text":"aufbauen"},{"id":"2","text":"aufhalten"},{"id":"3","text":"aufgeben"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Aufgeben means to give up an attempt; the past participle is aufgegeben.","de":"Aufgeben bedeutet hier, einen Versuch abzubrechen; das Partizip II ist aufgegeben."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach zehn Versuchen gelang die Reparatur immer noch nicht. Trotzdem wollte Nina nicht aufgeben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L89 (cddd2255d0a1e3d6a06a2602bc26911f35c2e3960c835d4fde594dc30d2e3e7c), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
