INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190000","revision":1,"targetId":"80000000-0000-4000-8000-000000001900","prompt":"Die Regel gilt nicht nur in Bayern, sondern in allen Bundesländern. Sie gilt ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The statement concerns all federal states, not one local area.","de":"Die Aussage betrifft alle Bundesländer und nicht nur einen Ort."},"options":[{"id":"0","text":"regional"},{"id":"1","text":"örtlich"},{"id":"2","text":"bundesweit"},{"id":"3","text":"vorübergehend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Bundesweit means nationwide across the federal territory.","de":"Bundesweit bedeutet im ganzen Bundesgebiet."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Regel gilt nicht nur in Bayern, sondern in allen Bundesländern. Sie gilt bundesweit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L80 (b5bd319f16d920f8b24633798369b88a3e12e3740b0f832ffda49d075e2a6bda), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
