INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190100","revision":1,"targetId":"80000000-0000-4000-8000-000000001910","prompt":"Die Unterlagen liegen nicht mehr auf Papier vor, sondern werden ___ gespeichert.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The information is handled electronically, not on paper.","de":"Die Informationen werden elektronisch statt auf Papier verarbeitet."},"options":[{"id":"0","text":"handschriftlich"},{"id":"1","text":"gedruckt"},{"id":"2","text":"digital"},{"id":"3","text":"analog"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Digital means electronic or computer-based, as opposed to analog or paper-based.","de":"Digital bedeutet elektronisch oder computergestützt, im Gegensatz zu analog."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Unterlagen liegen nicht mehr auf Papier vor, sondern werden digital gespeichert.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L94 (37748436b40a799a5245f6fc48bdb58e53179c10fbdc6156b74cb21dac177d03), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
