INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190110","revision":1,"targetId":"80000000-0000-4000-8000-000000001911","prompt":"Beim Treffen blieb er höflich, vermied aber persönliche Gespräche und hielt Abstand. Er wirkte ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person stays polite but avoids personal closeness.","de":"Die Person bleibt höflich, vermeidet aber persönliche Nähe."},"options":[{"id":"0","text":"vertraut"},{"id":"1","text":"herzlich"},{"id":"2","text":"distanziert"},{"id":"3","text":"überschwänglich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Distanziert means reserved or detached in social behavior.","de":"Distanziert bedeutet im Umgang zurückhaltend oder kühl."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Beim Treffen blieb er höflich, vermied aber persönliche Gespräche und hielt Abstand. Er wirkte distanziert.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L96 (d0b1842f6326dce3c0ae6c4b990bc3ac3daaaa1cd6906e0f52d106925e6eb665), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
