INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190121","revision":1,"targetId":"80000000-0000-4000-8000-000000001912","prompt":"Der neue Mitarbeiter duzte sofort alle Kunden und berührte sie ungefragt an der Schulter. Das wirkte ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone crosses personal boundaries without being invited.","de":"Jemand überschreitet persönliche Grenzen ohne Zustimmung."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"professionell"},{"id":"1","text":"höflich"},{"id":"2","text":"förmlich"},{"id":"3","text":"distanzlos"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Distanzlos means overfamiliar or intrusive, not discreet or respectful.","de":"Distanzlos bedeutet aufdringlich oder ohne angemessenen Abstand."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Mitarbeiter duzte sofort alle Kunden und berührte sie ungefragt an der Schulter. Das wirkte distanzlos.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L97 (a464414d8231dd334f0806b2550f13ca5561f568616758794beff7728520b076), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
