INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190151','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190151","revision":1,"targetId":"80000000-0000-4000-8000-000000001915","prompt":"Die meisten Teams schaffen 12 Aufgaben pro Woche. Unser Team schafft ebenfalls 12 und liegt damit im ___ Bereich.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The context concerns a mean or typical level.","de":"Gesucht ist ein mittlerer beziehungsweise typischer Wert."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"extremen"},{"id":"1","text":"untersten"},{"id":"2","text":"außergewöhnlichen"},{"id":"3","text":"durchschnittlichen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Durchschnittlich means average; it does not mean the highest or lowest.","de":"Durchschnittlich bedeutet im Mittel oder im üblichen Bereich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die meisten Teams schaffen 12 Aufgaben pro Woche. Unser Team schafft ebenfalls 12 und liegt damit im durchschnittlichen Bereich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L103 (e26a654d9783aa24fab285f1f5edb5e8be3e3eb38a0ed5241cf8d75cff2cb658), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
