INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190170","revision":1,"targetId":"80000000-0000-4000-8000-000000001917","prompt":"Der Markt verändert sich rasch, und jede Woche entstehen neue Angebote. Er entwickelt sich sehr ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The situation changes quickly and remains active.","de":"Die Entwicklung ist schnell und in Bewegung."},"options":[{"id":"0","text":"statisch"},{"id":"1","text":"träge"},{"id":"2","text":"dynamisch"},{"id":"3","text":"gleichförmig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Dynamisch means dynamic or actively changing, rather than static.","de":"Dynamisch bedeutet bewegt oder sich rasch entwickelnd."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Markt verändert sich rasch, und jede Woche entstehen neue Angebote. Er entwickelt sich sehr dynamisch.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L105 (99db810a1e08046ba11ac6f97e187e3fd9407c45f0c30c547a3c78fa3c054b3c), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
