INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000190191','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000190191","revision":1,"targetId":"80000000-0000-4000-8000-000000001919","prompt":"Der Kurs half fast allen Teilnehmenden, die Prüfung zu bestehen. Die Vorbereitung war sehr ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The action actually achieves its goal.","de":"Die Maßnahme erreicht das angestrebte Ziel."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"nutzlos"},{"id":"1","text":"vergeblich"},{"id":"2","text":"ungeeignet"},{"id":"3","text":"effektiv"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Effektiv means effective, producing the intended result, not necessarily inexpensive.","de":"Effektiv bedeutet wirksam, also das gewünschte Ergebnis erreichend."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Kurs half fast allen Teilnehmenden, die Prüfung zu bestehen. Die Vorbereitung war sehr effektiv.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adjectives.jsonl:L108 (d498c668258176ecf354e17a93a2a59b4660a02c02585996d3210a55e5918039), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
