INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200000","revision":1,"targetId":"80000000-0000-4000-8000-000000002000","prompt":"Die drei Kurse beginnen an unterschiedlichen Tagen, aber ___ um 9 Uhr.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The same detail applies to each group or occurrence separately.","de":"Dieselbe Angabe gilt für jede Gruppe oder jeden Fall einzeln."},"options":[{"id":"0","text":"selten"},{"id":"1","text":"niemals"},{"id":"2","text":"jeweils"},{"id":"3","text":"gestern"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Jeweils means in each case or each time, not only once overall.","de":"Jeweils bedeutet in jedem einzelnen Fall oder jedes Mal."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die drei Kurse beginnen an unterschiedlichen Tagen, aber jeweils um 9 Uhr.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L102 (9f8cd94595a603b6769c992b0a6bb4b73bb2341f3ce363fef7e7132486751b1a), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
