INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200001','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200001","revision":1,"targetId":"80000000-0000-4000-8000-000000002000","prompt":"Die acht Geräte werden gleichmäßig auf vier Gruppen verteilt. Jede Gruppe erhält ___ genau zwei Tablets.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The same detail applies to each group or occurrence separately.","de":"Dieselbe Angabe gilt für jede Gruppe oder jeden Fall einzeln."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"ungefähr"},{"id":"1","text":"jeweils"},{"id":"2","text":"selten"},{"id":"3","text":"zunächst"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Jeweils means in each case or each time, not only once overall.","de":"Jeweils bedeutet in jedem einzelnen Fall oder jedes Mal."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die acht Geräte werden gleichmäßig auf vier Gruppen verteilt. Jede Gruppe erhält jeweils genau zwei Tablets.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L102 (9f8cd94595a603b6769c992b0a6bb4b73bb2341f3ce363fef7e7132486751b1a), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
