INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200011","revision":1,"targetId":"80000000-0000-4000-8000-000000002001","prompt":"Nach dem Unfall konnte sie vor Schmerzen ___ gehen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The action is difficult and almost impossible.","de":"Die Handlung ist schwierig und fast nicht möglich."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"problemlos"},{"id":"1","text":"kaum"},{"id":"2","text":"schnell"},{"id":"3","text":"mühelos"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Kaum means hardly or barely, unlike easily or clearly.","de":"Kaum bedeutet fast nicht oder nur mit Mühe."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach dem Unfall konnte sie vor Schmerzen kaum gehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L103 (d6492237393da343a3ed647d72582155408dc614905ebab1e1bcba92cf441d9b), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
