INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200040","revision":1,"targetId":"80000000-0000-4000-8000-000000002004","prompt":"Du brauchst die Unterlagen nicht mehr zu schicken; sie sind ___ angekommen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The action was completed well before the present moment.","de":"Die Handlung ist schon vor längerer Zeit abgeschlossen worden."},"options":[{"id":"0","text":"morgen"},{"id":"1","text":"später"},{"id":"2","text":"längst"},{"id":"3","text":"bald"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Längst means long since or already some time ago.","de":"Längst bedeutet schon seit Langem oder schon vor längerer Zeit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Du brauchst die Unterlagen nicht mehr zu schicken; sie sind längst angekommen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L107 (948683e09664a358a4f2e1074d4face5943c17dabf749726ea3189492bf2ad50), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
