INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200070","revision":1,"targetId":"80000000-0000-4000-8000-000000002007","prompt":"Die beiden Abteilungen arbeiten nicht getrennt, sondern ___ an einem Projekt.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"People cooperate or speak directly with each other.","de":"Menschen arbeiten zusammen oder sprechen direkt miteinander."},"options":[{"id":"0","text":"gegeneinander"},{"id":"1","text":"nacheinander"},{"id":"2","text":"miteinander"},{"id":"3","text":"allein"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Miteinander means with one another, unlike against one another.","de":"Miteinander bedeutet gemeinsam oder wechselseitig, nicht gegeneinander."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die beiden Abteilungen arbeiten nicht getrennt, sondern miteinander an einem Projekt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L116 (44f5cb7915fd23b4846825844a2e241d0e37e5cc394af95c781a6b397cc43055), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
