INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200071','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200071","revision":1,"targetId":"80000000-0000-4000-8000-000000002007","prompt":"Statt E-Mails hin und her zu schicken, sollten wir direkt ___ sprechen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"People cooperate or speak directly with each other.","de":"Menschen arbeiten zusammen oder sprechen direkt miteinander."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"gegeneinander"},{"id":"1","text":"nebeneinander"},{"id":"2","text":"durcheinander"},{"id":"3","text":"miteinander"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Miteinander means with one another, unlike against one another.","de":"Miteinander bedeutet gemeinsam oder wechselseitig, nicht gegeneinander."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Statt E-Mails hin und her zu schicken, sollten wir direkt miteinander sprechen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L116 (44f5cb7915fd23b4846825844a2e241d0e37e5cc394af95c781a6b397cc43055), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
