INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200080","revision":1,"targetId":"80000000-0000-4000-8000-000000002008","prompt":"Das Auto blieb genau ___ auf der Kreuzung stehen, nicht am Straßenrand.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The event happens right at the center or during an ongoing moment.","de":"Etwas geschieht genau im Zentrum oder während eines laufenden Ereignisses."},"options":[{"id":"0","text":"außerhalb"},{"id":"1","text":"hinter"},{"id":"2","text":"mitten"},{"id":"3","text":"neben"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Mitten means right in the middle, often followed by auf or in.","de":"Mitten bedeutet genau in der Mitte, oft in Verbindungen wie mitten auf oder mitten in."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Auto blieb genau mitten auf der Kreuzung stehen, nicht am Straßenrand.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L117 (44245bc867dc068038e3ac3e1cfbb035af6ea3499c8aeb1cc3f03207147d36a6), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
