INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200101","revision":1,"targetId":"80000000-0000-4000-8000-000000002010","prompt":"Die Ursache ist noch nicht bestätigt. ___ war ein Softwarefehler verantwortlich.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The outcome or cause is not yet confirmed.","de":"Das Ergebnis oder die Ursache ist noch nicht sicher."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"nachweislich"},{"id":"1","text":"zweifellos"},{"id":"2","text":"definitiv"},{"id":"3","text":"möglicherweise"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Möglicherweise means possibly; it does not express certainty.","de":"Möglicherweise bedeutet vielleicht und drückt keine Gewissheit aus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Ursache ist noch nicht bestätigt. möglicherweise war ein Softwarefehler verantwortlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L119 (3663d5ec9a347d3ca2f68a9afdbeec1ccf962289b5afb7b9288b57801b2af23a), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
