INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200110","revision":1,"targetId":"80000000-0000-4000-8000-000000002011","prompt":"Bitte senden Sie die Unterlagen ___ früh, damit wir noch Zeit für die Prüfung haben.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The speaker wants to maximize something within practical limits.","de":"Etwas soll innerhalb der Möglichkeiten so stark wie möglich geschehen."},"options":[{"id":"0","text":"gestern"},{"id":"1","text":"später"},{"id":"2","text":"möglichst"},{"id":"3","text":"selten"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Möglichst means as ... as possible, such as möglichst früh.","de":"Möglichst bedeutet so ... wie möglich, etwa möglichst früh."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Bitte senden Sie die Unterlagen möglichst früh, damit wir noch Zeit für die Prüfung haben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L120 (734fee36ae363370eba19c6790fb87458ce6f164ce70540b3b8abc2cdb53eaa7), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
