INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200120","revision":1,"targetId":"80000000-0000-4000-8000-000000002012","prompt":"Jetzt haben wir noch Unterricht; ___ gehen wir gemeinsam essen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The action happens after what is going on now.","de":"Die Handlung findet nach der jetzigen Tätigkeit statt."},"options":[{"id":"0","text":"gestern"},{"id":"1","text":"vorhin"},{"id":"2","text":"nachher"},{"id":"3","text":"damals"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Nachher means later or afterwards, not yesterday or in the distant past.","de":"Nachher bedeutet später oder anschließend, nicht gestern oder damals."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Jetzt haben wir noch Unterricht; nachher gehen wir gemeinsam essen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L122 (811632bb5a160a3bbe2887c50749aa96b492709e50823a6201e72b932d74bcf4), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
