INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200130','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200130","revision":1,"targetId":"80000000-0000-4000-8000-000000002013","prompt":"Sie studiert Vollzeit und arbeitet ___ an zwei Abenden pro Woche.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"One activity takes place in addition to the main one.","de":"Eine Tätigkeit geschieht zusätzlich zur Hauptbeschäftigung."},"options":[{"id":"0","text":"ausschließlich"},{"id":"1","text":"hauptberuflich"},{"id":"2","text":"nebenbei"},{"id":"3","text":"niemals"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Nebenbei means on the side or incidentally, alongside another activity.","de":"Nebenbei bedeutet zusätzlich oder während einer anderen Tätigkeit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie studiert Vollzeit und arbeitet nebenbei an zwei Abenden pro Woche.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L124 (c268c30e9021db9e73c827879c49e0347000b3747240e9645c7d58ec7284bcb3), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
