INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200150","revision":1,"targetId":"80000000-0000-4000-8000-000000002015","prompt":"Ich habe ___ meine frühere Lehrerin zufällig getroffen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The event happened recently in the past.","de":"Das Ereignis liegt erst kurze Zeit zurück."},"options":[{"id":"0","text":"morgen"},{"id":"1","text":"künftig"},{"id":"2","text":"neulich"},{"id":"3","text":"demnächst"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Neulich means recently or the other day, not in the future.","de":"Neulich bedeutet vor Kurzem oder kürzlich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich habe neulich meine frühere Lehrerin zufällig getroffen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L126 (6e4c70a0f29f95b749f73907e0eeea4468baf9e53f4be812be067aa5786cffa6), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
