INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000200160','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000200160","revision":1,"targetId":"80000000-0000-4000-8000-000000002016","prompt":"Wir haben jedes Regal abgesucht, aber das Buch war ___ zu finden.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"Every location has been checked, with no success.","de":"Alle Orte wurden überprüft, aber ohne Erfolg."},"options":[{"id":"0","text":"überall"},{"id":"1","text":"hier"},{"id":"2","text":"nirgendwo"},{"id":"3","text":"dort"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Nirgendwo means nowhere, in contrast to überall.","de":"Nirgendwo bedeutet an keinem Ort, im Gegensatz zu überall."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wir haben jedes Regal abgesucht, aber das Buch war nirgendwo zu finden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/adverbs.jsonl:L130 (f8a9f216e862c183e4e12b4ff98b48800904fbf3ff5d13a6a2abc8e7884557fb), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
