INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210010","revision":1,"targetId":"80000000-0000-4000-8000-000000002101","prompt":"Für die Sicherheitsunterweisung ist die ___ aller Beschäftigten erforderlich.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person must be there, not absent.","de":"Die Person muss vor Ort sein und darf nicht fehlen."},"options":[{"id":"0","text":"Abwesenheit"},{"id":"1","text":"Verspätung"},{"id":"2","text":"Anwesenheit"},{"id":"3","text":"Vertretung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Anwesenheit means presence or attendance, the opposite of Abwesenheit.","de":"Anwesenheit bedeutet das Anwesendsein und ist das Gegenteil von Abwesenheit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Sicherheitsunterweisung ist die Anwesenheit aller Beschäftigten erforderlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L102 (2a17b71c933546619cdd8694c92425674980b97153f69984d8cafa7c3a8fbb47), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
