INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210121","revision":1,"targetId":"80000000-0000-4000-8000-000000002112","prompt":"Sein Aufenthaltstitel erlaubt ihm das Wohnen, aber noch keine Beschäftigung. Für den Job braucht er eine ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person needs official authorization to take the job.","de":"Die Person benötigt eine behördliche Berechtigung, um zu arbeiten."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Rechnung"},{"id":"1","text":"Fahrerlaubnis"},{"id":"2","text":"Bescheinigung"},{"id":"3","text":"Arbeitserlaubnis"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Arbeitserlaubnis means work authorization; whether it is needed depends on status and law.","de":"Arbeitserlaubnis bedeutet Arbeitserlaubnis; ob sie nötig ist, hängt vom Aufenthaltsstatus und Recht ab."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sein Aufenthaltstitel erlaubt ihm das Wohnen, aber noch keine Beschäftigung. Für den Job braucht er eine Arbeitserlaubnis.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L123 (8e3ed30442fa12176cae73e5427e69e47387bb16bb558fb4ef474b915fcccf5c), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.