INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210141','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210141","revision":1,"targetId":"80000000-0000-4000-8000-000000002114","prompt":"Während des ___ legten viele Beschäftigte die Arbeit nieder.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"A union organizes collective action in a labor dispute.","de":"Eine Gewerkschaft organisiert gemeinsame Maßnahmen im Tarifkonflikt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Arbeitsbeginns"},{"id":"1","text":"Urlaubs"},{"id":"2","text":"Feierabends"},{"id":"3","text":"Arbeitskampfs"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Arbeitskampf means industrial action, including strikes, not ordinary work.","de":"Arbeitskampf bezeichnet kollektive Maßnahmen wie einen Streik."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Während des Arbeitskampfs legten viele Beschäftigte die Arbeit nieder.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L125 (edd3c3f32471345cd0c9c4fd2778ccbce2d1dcb16309fb0b1169f57ef9aa6a2a), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
