INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210150","revision":1,"targetId":"80000000-0000-4000-8000-000000002115","prompt":"Die Vorgesetzte bewertet, wie sorgfältig und zuverlässig die Aufgaben erledigt wurden. Sie beurteilt die ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence evaluates work output or quality.","de":"Es geht um die Menge oder Qualität der geleisteten Arbeit."},"options":[{"id":"0","text":"Arbeitszeit"},{"id":"1","text":"Urlaubsplanung"},{"id":"2","text":"Arbeitsleistung"},{"id":"3","text":"Arbeitskleidung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Arbeitsleistung means work performance or work delivered.","de":"Arbeitsleistung bezeichnet die erbrachte Arbeitsleistung nach Umfang oder Qualität."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Vorgesetzte bewertet, wie sorgfältig und zuverlässig die Aufgaben erledigt wurden. Sie beurteilt die Arbeitsleistung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L126 (f96456e634418bcccd65d196b1d702cc2a3a8f7c3f962a89ff462060c6c95ee7), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
