INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210151','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210151","revision":1,"targetId":"80000000-0000-4000-8000-000000002115","prompt":"Durch die neue Maschine schafft das Team mehr Stücke pro Stunde. Seine ___ ist gestiegen.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence evaluates work output or quality.","de":"Es geht um die Menge oder Qualität der geleisteten Arbeit."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Fehlzeit"},{"id":"1","text":"Urlaubsdauer"},{"id":"2","text":"Miete"},{"id":"3","text":"Arbeitsleistung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Arbeitsleistung means work performance or work delivered.","de":"Arbeitsleistung bezeichnet die erbrachte Arbeitsleistung nach Umfang oder Qualität."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Durch die neue Maschine schafft das Team mehr Stücke pro Stunde. Seine Arbeitsleistung ist gestiegen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L126 (f96456e634418bcccd65d196b1d702cc2a3a8f7c3f962a89ff462060c6c95ee7), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
