INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210170","revision":1,"targetId":"80000000-0000-4000-8000-000000002117","prompt":"Von 1.000 Erwerbspersonen sind 50 arbeitslos. Die ___ beträgt fünf Prozent.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The statistic is expressed as a percentage, not a number of people.","de":"Die Statistik wird in Prozent statt in Personen angegeben."},"options":[{"id":"0","text":"Arbeitslosenzahl"},{"id":"1","text":"Bevölkerungszahl"},{"id":"2","text":"Arbeitslosenquote"},{"id":"3","text":"Lohnsumme"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Arbeitslosenquote is the unemployment rate; Arbeitslosenzahl is a count.","de":"Arbeitslosenquote ist der Prozentwert, Arbeitslosenzahl die absolute Zahl."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Von 1.000 Erwerbspersonen sind 50 arbeitslos. Die Arbeitslosenquote beträgt fünf Prozent.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L128 (64fe939251932b1e9f65fbd7d7ce7b018c3bb134aa9b8083afb2048721c40c52), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
