INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000210180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000210180","revision":1,"targetId":"80000000-0000-4000-8000-000000002118","prompt":"Beschäftigte und Arbeitgeber zahlen Beiträge in eine Versicherung, die bei Arbeitslosigkeit Leistungen finanzieren kann. Das ist die ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The contributions relate specifically to unemployment risk.","de":"Die Beiträge sichern das Risiko der Arbeitslosigkeit ab."},"options":[{"id":"0","text":"Krankenversicherung"},{"id":"1","text":"Haftpflichtversicherung"},{"id":"2","text":"Arbeitslosenversicherung"},{"id":"3","text":"Reiseversicherung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Arbeitslosenversicherung is unemployment insurance, distinct from health or pension insurance.","de":"Arbeitslosenversicherung ist die Versicherung gegen Arbeitslosigkeit, nicht Kranken- oder Rentenversicherung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Beschäftigte und Arbeitgeber zahlen Beiträge in eine Versicherung, die bei Arbeitslosigkeit Leistungen finanzieren kann. Das ist die Arbeitslosenversicherung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L129 (e84a84af2c023544eafd3106dbba560e27512c224e446f9c9a514790f3b50f07), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
