INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230000","revision":1,"targetId":"80000000-0000-4000-8000-000000002300","prompt":"Mit der neuen Software schafft das Team dieselbe Arbeit in der halben Zeit. Der Ablauf ist jetzt ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Compare resources used with the same result.","de":"Vergleiche den Aufwand mit dem erzielten Ergebnis."},"options":[{"id":"0","text":"effizient"},{"id":"1","text":"aufwendig"},{"id":"2","text":"langsam"},{"id":"3","text":"umständlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"effizient means achieving results with relatively little time or energy.","de":"effizient bedeutet, mit wenig Zeit oder Energie ein gutes Ergebnis zu erzielen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mit der neuen Software schafft das Team dieselbe Arbeit in der halben Zeit. Der Ablauf ist jetzt effizient.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L109 (1e1c7f8a7d5b64b9976b57b2aede6aaba8429257fd5e7819bf0f46935986e134), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
