INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230010","revision":1,"targetId":"80000000-0000-4000-8000-000000002301","prompt":"Sie bekommt für ihre regelmäßige Hilfe im Tierheim kein Geld. Sie arbeitet dort ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The service is unpaid and for a community cause.","de":"Die Tätigkeit wird ohne Bezahlung für einen guten Zweck ausgeübt."},"options":[{"id":"0","text":"hauptberuflich"},{"id":"1","text":"ehrenamtlich"},{"id":"2","text":"gewerblich"},{"id":"3","text":"angestellt"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"ehrenamtlich refers to voluntary, normally unpaid service for a cause or organization.","de":"ehrenamtlich bezeichnet freiwilliges, normalerweise unbezahltes Engagement."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie bekommt für ihre regelmäßige Hilfe im Tierheim kein Geld. Sie arbeitet dort ehrenamtlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L111 (175b15b2214ff7fd5a6d5ef4d33aa2edcf9e9bee61c9aed3e2296fbca0f6bed0), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
