INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230021','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230021","revision":1,"targetId":"80000000-0000-4000-8000-000000002302","prompt":"Der Forscher setzt sich sehr anspruchsvolle Ziele und verfolgt sie konsequent. Er gilt als ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person strives persistently for high achievement.","de":"Die Person arbeitet beharrlich auf hohe Ziele hin."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"ehrgeizig"},{"id":"1","text":"bequem"},{"id":"2","text":"ziellos"},{"id":"3","text":"gleichgültig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"ehrgeizig describes someone strongly motivated to achieve challenging goals.","de":"ehrgeizig beschreibt Menschen, die anspruchsvolle Ziele entschlossen verfolgen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Forscher setzt sich sehr anspruchsvolle Ziele und verfolgt sie konsequent. Er gilt als ehrgeizig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L112 (b47116551a0e8633eed7bc258cd6578462dd0c16e674a5eacbd69150d1b2268b), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
