INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230041','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230041","revision":1,"targetId":"80000000-0000-4000-8000-000000002304","prompt":"Im Projekt entscheidet er ohne ständige Rücksprache über seine Aufgaben und muss seine Entscheidungen selbst begründen. Er handelt ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person sets priorities and answers for the results.","de":"Die Person setzt Prioritäten selbst und steht für die Ergebnisse ein."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"eigenverantwortlich"},{"id":"1","text":"fremdbestimmt"},{"id":"2","text":"gleichgültig"},{"id":"3","text":"unüberlegt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"eigenverantwortlich means acting independently while accepting responsibility.","de":"eigenverantwortlich bedeutet, selbstständig zu entscheiden und Verantwortung zu tragen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Projekt entscheidet er ohne ständige Rücksprache über seine Aufgaben und muss seine Entscheidungen selbst begründen. Er handelt eigenverantwortlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L116 (1051626518203581916e4dcf73bcee8cce70ba91c218560dc2d22eeebb4ab766), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental pro