INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230180","revision":1,"targetId":"80000000-0000-4000-8000-000000002318","prompt":"Für die Herstellung einer Tonne Aluminium wird sehr viel Strom benötigt. Der Prozess ist ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The process uses a very large amount of electricity.","de":"Der Vorgang benötigt besonders viel Strom."},"options":[{"id":"0","text":"energiesparend"},{"id":"1","text":"energieintensiv"},{"id":"2","text":"geräuschlos"},{"id":"3","text":"wartungsarm"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"energieintensiv means requiring large amounts of energy.","de":"energieintensiv bedeutet, dass ein Prozess sehr viel Energie benötigt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Herstellung einer Tonne Aluminium wird sehr viel Strom benötigt. Der Prozess ist energieintensiv.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L133 (68aa0218c5ebed6dae2669837291324157036859e86862e30c6c4b2bfb919315), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
