INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000230190','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000230190","revision":1,"targetId":"80000000-0000-4000-8000-000000002319","prompt":"Die Mitarbeiterin übernimmt freiwillig zusätzliche Aufgaben und setzt sich für das Team ein. Sie ist sehr ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person willingly invests extra effort.","de":"Die Person zeigt freiwillig besonderen Einsatz."},"options":[{"id":"0","text":"passiv"},{"id":"1","text":"engagiert"},{"id":"2","text":"gleichgültig"},{"id":"3","text":"nachlässig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"engagiert means committed and actively dedicated to a task.","de":"engagiert bedeutet, sich mit großem Einsatz für eine Sache einzusetzen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Mitarbeiterin übernimmt freiwillig zusätzliche Aufgaben und setzt sich für das Team ein. Sie ist sehr engagiert.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 lexical exercises from pinned apps/web/data/pos/adjectives.jsonl:L135 (a68bd0439813e90c05c4ec4010f3b1fdbfbadeb6b477a004b7e0c1a0e685f330), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
