INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240000","revision":1,"targetId":"80000000-0000-4000-8000-000000002400","prompt":"Jeden Werktag beginnt die Schicht um acht, nur heute um neun. ___ beginnt sie um acht.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Compare the regular schedule with an exception.","de":"Vergleiche den üblichen Ablauf mit einer Ausnahme."},"options":[{"id":"0","text":"Ausnahmsweise"},{"id":"1","text":"Normalerweise"},{"id":"2","text":"Selten"},{"id":"3","text":"Nie"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"normalerweise indicates the usual pattern, allowing exceptions.","de":"normalerweise bezeichnet den Regelfall, von dem es Ausnahmen geben kann."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Jeden Werktag beginnt die Schicht um acht, nur heute um neun. Normalerweise beginnt sie um acht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L135 (5e0e3db1bbb203526c5a821308dc61d9dadbae4eb4f1e85742713f4efe749255), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
