INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240001','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240001","revision":1,"targetId":"80000000-0000-4000-8000-000000002400","prompt":"Der Bus fährt an Schultagen alle zehn Minuten. ___ muss man nicht lange warten.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Compare the regular schedule with an exception.","de":"Vergleiche den üblichen Ablauf mit einer Ausnahme."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Niemals"},{"id":"1","text":"Zufällig"},{"id":"2","text":"Normalerweise"},{"id":"3","text":"Ausnahmsweise"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"normalerweise indicates the usual pattern, allowing exceptions.","de":"normalerweise bezeichnet den Regelfall, von dem es Ausnahmen geben kann."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Bus fährt an Schultagen alle zehn Minuten. Normalerweise muss man nicht lange warten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L135 (5e0e3db1bbb203526c5a821308dc61d9dadbae4eb4f1e85742713f4efe749255), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
