INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240010","revision":1,"targetId":"80000000-0000-4000-8000-000000002401","prompt":"Die Vorbereitungen sind abgeschlossen. ___ können wir anfangen.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The previous stage has ended and the next begins.","de":"Eine frühere Phase endet und der nächste Schritt beginnt."},"options":[{"id":"0","text":"Damals"},{"id":"1","text":"Früher"},{"id":"2","text":"Nun"},{"id":"3","text":"Gestern"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"nun means now, often introducing the next step or a changed situation.","de":"nun bedeutet jetzt und markiert häufig einen neuen Schritt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Vorbereitungen sind abgeschlossen. Nun können wir anfangen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L136 (372e2cea6c9eac47d98a0a03426c710e96980b9b5f4fdf873b345ca9d5a1c098), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
