INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240040","revision":1,"targetId":"80000000-0000-4000-8000-000000002404","prompt":"Statt dem Weg am Rand zu folgen, gingen die Wanderer ___ über die Wiese.","instruction":{"en":"Choose the word describing movement across the meadow from one side to the other, rather than movement along its edge or a return journey.","de":"Wähle das Wort für die Bewegung über die Wiese von einer Seite zur anderen, nicht für eine Bewegung am Rand oder eine Rückkehr."},"hint":{"en":"Think of crossing from one edge to the opposite edge.","de":"Denke an den Weg von einem Rand zum gegenüberliegenden Rand."},"options":[{"id":"0","text":"parallel"},{"id":"1","text":"quer"},{"id":"2","text":"entlang"},{"id":"3","text":"zurück"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"quer means across or crosswise rather than lengthwise.","de":"quer bedeutet von einer Seite zur anderen oder entgegen der Längsrichtung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Statt dem Weg am Rand zu folgen, gingen die Wanderer quer über die Wiese.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L143 (a6df8cc38f8e51bd0cf8dfe1c9550a28ac22d1cf4de40dd3fa62768cdc091349), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
