INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240041','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240041","revision":1,"targetId":"80000000-0000-4000-8000-000000002404","prompt":"Der umgestürzte Baum blockierte beide Fahrspuren, weil er ___ auf der Straße lag.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The direction cuts across the main axis.","de":"Die Richtung verläuft über die Hauptachse hinweg."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"längs"},{"id":"1","text":"gerade"},{"id":"2","text":"quer"},{"id":"3","text":"parallel"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"quer means across or crosswise rather than lengthwise.","de":"quer bedeutet von einer Seite zur anderen oder entgegen der Längsrichtung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der umgestürzte Baum blockierte beide Fahrspuren, weil er quer auf der Straße lag.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L143 (a6df8cc38f8e51bd0cf8dfe1c9550a28ac22d1cf4de40dd3fa62768cdc091349), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
