INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240071','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240071","revision":1,"targetId":"80000000-0000-4000-8000-000000002407","prompt":"Vor einem lauten Telefonat fragt sie, ob die Kollegen konzentriert arbeiten müssen. Sie handelt ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person adapts behavior to avoid disturbing others.","de":"Die Person nimmt Rücksicht, um andere nicht zu stören."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"rücksichtsvoll"},{"id":"1","text":"egoistisch"},{"id":"2","text":"achtlos"},{"id":"3","text":"unaufmerksam"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"rücksichtsvoll means considerate of other people''s needs.","de":"rücksichtsvoll bedeutet, auf die Bedürfnisse anderer zu achten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Vor einem lauten Telefonat fragt sie, ob die Kollegen konzentriert arbeiten müssen. Sie handelt rücksichtsvoll.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L149 (f47b67c9e5862e315ad5183c7d7dfc0fb9b9e5bea0663996bb27d628bca79040), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
