INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240080","revision":1,"targetId":"80000000-0000-4000-8000-000000002408","prompt":"Der Wagen war mit der Front zuerst in die enge Einfahrt gefahren und konnte dort nicht wenden; er musste ___ herausfahren.","instruction":{"en":"Choose the word describing which end of the car leads as it exits, rather than the shape of its path.","de":"Wähle das Wort dafür, welches Ende des Autos beim Herausfahren vorausfährt, nicht für den Verlauf seiner Fahrspur."},"hint":{"en":"The vehicle moves rear end first.","de":"Das Fahrzeug bewegt sich mit dem Heck voraus."},"options":[{"id":"0","text":"seitwärts"},{"id":"1","text":"vorwärts"},{"id":"2","text":"rückwärts"},{"id":"3","text":"geradeaus"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"rückwärts means in a backward direction.","de":"rückwärts bedeutet in Richtung nach hinten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Wagen war mit der Front zuerst in die enge Einfahrt gefahren und konnte dort nicht wenden; er musste rückwärts herausfahren.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L150 (935702a3f9555fa73069b20585a02430a66d1b1dee9a087139123ad2f38ed492), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
