INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240081','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240081","revision":1,"targetId":"80000000-0000-4000-8000-000000002408","prompt":"Die Kamera zeigt, wie der Stapler mit dem Heck zuerst ___ aus der Halle fährt.","instruction":{"en":"Choose the direction word that states which end of the forklift leads, rather than whether its path is straight.","de":"Wähle das Richtungswort dafür, welches Ende des Staplers vorausfährt, nicht dafür, ob seine Fahrspur gerade verläuft."},"hint":{"en":"The vehicle moves rear end first.","de":"Das Fahrzeug bewegt sich mit dem Heck voraus."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"rückwärts"},{"id":"1","text":"vorwärts"},{"id":"2","text":"seitlich"},{"id":"3","text":"geradeaus"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"rückwärts means in a backward direction.","de":"rückwärts bedeutet in Richtung nach hinten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kamera zeigt, wie der Stapler mit dem Heck zuerst rückwärts aus der Halle fährt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L150 (935702a3f9555fa73069b20585a02430a66d1b1dee9a087139123ad2f38ed492), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
