INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240090","revision":1,"targetId":"80000000-0000-4000-8000-000000002409","prompt":"Nach vielen vergeblichen Versuchen funktionierte die Anmeldung ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The outcome comes after earlier effort.","de":"Das Ergebnis folgt auf vorherige Bemühungen."},"options":[{"id":"0","text":"anfangs"},{"id":"1","text":"niemals"},{"id":"2","text":"schließlich"},{"id":"3","text":"vorher"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"schließlich means eventually or in the end, after preceding events.","de":"schließlich bedeutet am Ende einer Entwicklung oder nach mehreren Versuchen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach vielen vergeblichen Versuchen funktionierte die Anmeldung schließlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L151 (1b1f68b5af9ec1cd03c66d71d7d137237850e5e0d79ff8bf98f8250706913b27), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
