INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240091","revision":1,"targetId":"80000000-0000-4000-8000-000000002409","prompt":"Wir haben lange diskutiert und uns ___ auf einen Termin geeinigt.","instruction":{"en":"Choose the word presenting agreement as the successful final result of the long discussion, not an initial or absent result.","de":"Wähle das Wort, das die Einigung als erfolgreiches Endergebnis der langen Diskussion darstellt, nicht als vorläufiges oder ausgebliebenes Ergebnis."},"hint":{"en":"The outcome comes after earlier effort.","de":"Das Ergebnis folgt auf vorherige Bemühungen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"schließlich"},{"id":"1","text":"zunächst"},{"id":"2","text":"früher"},{"id":"3","text":"nie"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"schließlich means eventually or in the end, after preceding events.","de":"schließlich bedeutet am Ende einer Entwicklung oder nach mehreren Versuchen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wir haben lange diskutiert und uns schließlich auf einen Termin geeinigt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L151 (1b1f68b5af9ec1cd03c66d71d7d137237850e5e0d79ff8bf98f8250706913b27), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
