INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240100","revision":1,"targetId":"80000000-0000-4000-8000-000000002410","prompt":"Die Onlinebewerbung muss bis Freitag eingereicht sein. Reiche sie ___ am Freitag ein.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The deadline must not be exceeded.","de":"Der genannte Termin darf nicht überschritten werden."},"options":[{"id":"0","text":"frühestens"},{"id":"1","text":"spätestens"},{"id":"2","text":"ungefähr"},{"id":"3","text":"vielleicht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"spätestens marks the latest permissible time or deadline.","de":"spätestens bezeichnet den letztmöglichen Zeitpunkt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Onlinebewerbung muss bis Freitag eingereicht sein. Reiche sie spätestens am Freitag ein.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L157 (3093cdf9b1c1c1e1e5fe687a7b210e98ff5042b7c3f0869012a8e220a0ba6797), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
