INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240101","revision":1,"targetId":"80000000-0000-4000-8000-000000002410","prompt":"Der Zug fährt um acht. Du darfst schon früher kommen, musst aber bis 7:50 Uhr am Bahnsteig sein; nach 7:50 Uhr wäre es zu spät. Sei also ___ um 7:50 Uhr dort.","instruction":{"en":"Choose the expression marking the latest permitted arrival time.","de":"Wähle den Ausdruck für den letztmöglichen Ankunftszeitpunkt."},"hint":{"en":"The deadline must not be exceeded.","de":"Der genannte Termin darf nicht überschritten werden."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"vielleicht"},{"id":"1","text":"frühestens"},{"id":"2","text":"spätestens"},{"id":"3","text":"ungefähr"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"spätestens marks the latest permissible time or deadline.","de":"spätestens bezeichnet den letztmöglichen Zeitpunkt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Zug fährt um acht. Du darfst schon früher kommen, musst aber bis 7:50 Uhr am Bahnsteig sein; nach 7:50 Uhr wäre es zu spät. Sei also spätestens um 7:50 Uhr dort.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L157 (3093cdf9b1c1c1e1e5fe687a7b210e98ff5042b7c3f0869012a8e220a0ba6797), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
