INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240110","revision":1,"targetId":"80000000-0000-4000-8000-000000002411","prompt":"Ohne vorherige Planung entschied sie sich am Abend für einen Theaterbesuch. Das war ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"There was no plan or appointment in advance.","de":"Es gab vorher keinen Plan oder festen Termin."},"options":[{"id":"0","text":"langfristig"},{"id":"1","text":"spontan"},{"id":"2","text":"verpflichtend"},{"id":"3","text":"geplant"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"spontan means unplanned or decided on the spot.","de":"spontan bedeutet ohne vorherige Planung und aus dem Moment heraus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ohne vorherige Planung entschied sie sich am Abend für einen Theaterbesuch. Das war spontan.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L158 (415cfbf2204ba5b2b6124f78b033b0dee44ecae7f42f4a15cb0efabf8ead7706), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
