INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240120","revision":1,"targetId":"80000000-0000-4000-8000-000000002412","prompt":"Trotz des starken Windes schwankt das Gerüst nicht. Es steht ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"There is no significant movement or change.","de":"Es gibt keine starke Bewegung oder Veränderung."},"options":[{"id":"0","text":"wackelig"},{"id":"1","text":"locker"},{"id":"2","text":"stabil"},{"id":"3","text":"unsicher"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"stabil means steady, secure or not fluctuating.","de":"stabil bedeutet fest, sicher oder wenig schwankend."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Trotz des starken Windes schwankt das Gerüst nicht. Es steht stabil.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L159 (5487a7c1bf0e292b23b3e0f59288e0bc2c389bd58782ddda0baff1c5802743b8), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
