INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240131','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240131","revision":1,"targetId":"80000000-0000-4000-8000-000000002413","prompt":"Ein Straßenabschnitt ist vollständig gesperrt, der übrige Teil ist offen. Die Straße ist nur ___ befahrbar.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Only a portion is affected or completed.","de":"Nur ein Teil ist betroffen oder erledigt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"teilweise"},{"id":"1","text":"vollständig"},{"id":"2","text":"überhaupt nicht"},{"id":"3","text":"durchgehend"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"teilweise means partly rather than completely.","de":"teilweise bedeutet nur zum Teil, nicht vollständig."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ein Straßenabschnitt ist vollständig gesperrt, der übrige Teil ist offen. Die Straße ist nur teilweise befahrbar.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L160 (208460225f2939525b22b766eeede56979c5dd4e14febf46ad36f3f014c429fa), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
