INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240150","revision":1,"targetId":"80000000-0000-4000-8000-000000002415","prompt":"Ich habe den Namen noch nie gehört. Kennst du diese Person ___?","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The question concerns whether the situation is true in any degree, not how much of it is true.","de":"Die Frage betrifft, ob die Aussage grundsätzlich zutrifft, nicht in welchem Umfang."},"options":[{"id":"0","text":"üblicherweise"},{"id":"1","text":"überhaupt"},{"id":"2","text":"teilweise"},{"id":"3","text":"schließlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"überhaupt can emphasize ''at all'' in questions and negatives.","de":"überhaupt betont in Fragen und Verneinungen, ob etwas grundsätzlich zutrifft."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ich habe den Namen noch nie gehört. Kennst du diese Person überhaupt?","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L163 (27e7dbdb8f72287d09547a863c20682a4e26ffab2de022a4d51589bb17763266), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
