INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240151','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240151","revision":1,"targetId":"80000000-0000-4000-8000-000000002415","prompt":"Ist dieses Gerät ___ noch in Betrieb, oder wurde es längst abgeschaltet?","instruction":{"en":"Choose the word emphasizing the fundamental yes-or-no question of whether the device is still operating at all, rather than asking about partial or usual operation.","de":"Wähle das Wort, das die grundsätzliche Ja-Nein-Frage nach dem Weiterbetrieb verstärkt, statt nach einem teilweisen oder üblichen Betrieb zu fragen."},"hint":{"en":"The question concerns whether the situation is true in any degree, not how much of it is true.","de":"Die Frage betrifft, ob die Aussage grundsätzlich zutrifft, nicht in welchem Umfang."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"spätestens"},{"id":"1","text":"teilweise"},{"id":"2","text":"überhaupt"},{"id":"3","text":"üblicherweise"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"überhaupt can emphasize ''at all'' in questions and negatives.","de":"überhaupt betont in Fragen und Verneinungen, ob etwas grundsätzlich zutrifft."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ist dieses Gerät überhaupt noch in Betrieb, oder wurde es längst abgeschaltet?","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L163 (27e7dbdb8f72287d09547a863c20682a4e26ffab2de022a4d51589bb17763266), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
