INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000240191','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000240191","revision":1,"targetId":"80000000-0000-4000-8000-000000002419","prompt":"Die Bibliothek erhebt keine Leihgebühr. Man kann die Bücher ___ ausleihen.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"No fee is charged for the service.","de":"Für die Leistung wird kein Geld verlangt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"gegen Bezahlung"},{"id":"1","text":"auf Rechnung"},{"id":"2","text":"umsonst"},{"id":"3","text":"gegen Gebühr"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"umsonst can mean free of charge; a separate sense is ''in vain''.","de":"umsonst kann kostenlos bedeuten; eine andere Bedeutung ist vergeblich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Bibliothek erhebt keine Leihgebühr. Man kann die Bücher umsonst ausleihen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adverbs.jsonl:L168 (fd82d21f82869a1b70277b11ea6dd403e9dbaddd610bfe31188cad579321978a), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
