INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000250001','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000250001","revision":1,"targetId":"80000000-0000-4000-8000-000000002500","prompt":"Die Stadt will die Zahl der Menschen ohne Arbeit senken. Sie plant Maßnahmen gegen die ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The issue is people lacking jobs.","de":"Es geht darum, dass Menschen keine Arbeit haben."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Arbeitszeit"},{"id":"1","text":"Arbeitswelt"},{"id":"2","text":"Arbeitslosigkeit"},{"id":"3","text":"Arbeitsweise"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Arbeitslosigkeit refers to unemployment, not a particular benefit or unemployment rate.","de":"Arbeitslosigkeit bezeichnet das Fehlen von Beschäftigung, nicht eine bestimmte Leistung oder Quote."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Stadt will die Zahl der Menschen ohne Arbeit senken. Sie plant Maßnahmen gegen die Arbeitslosigkeit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/nouns.jsonl:L131 (f2015e69385d812a58553b6e43610ac2cf3f8686bd95571c700e49021eb03718), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
