INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000250011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000250011","revision":1,"targetId":"80000000-0000-4000-8000-000000002501","prompt":"Der Bericht untersucht, welche Berufe gefragt sind und wie viele offene Stellen es gibt. Er beschreibt den ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Consider vacancies and the availability of workers.","de":"Denke an offene Stellen und verfügbare Arbeitskräfte."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Arbeitsmarkt"},{"id":"1","text":"Arbeitsstil"},{"id":"2","text":"Arbeitsweg"},{"id":"3","text":"Arbeitsspeicher"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"Arbeitsmarkt means the labor market, where employers and job seekers meet.","de":"Arbeitsmarkt bezeichnet das Zusammenspiel von Stellenangeboten und Arbeitskräften."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Bericht untersucht, welche Berufe gefragt sind und wie viele offene Stellen es gibt. Er beschreibt den Arbeitsmarkt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/nouns.jsonl:L132 (79b78752b70515e1c0eb8a8b52412b691752f048d2ed8d2c4228cfe9158ec690), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
