INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000250020','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000250020","revision":1,"targetId":"80000000-0000-4000-8000-000000002502","prompt":"Für die Reparatur erhält der Techniker Werkzeug und Messgeräte. Das sind seine ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"These are objects needed to carry out the task.","de":"Gemeint sind Gegenstände, die man für die Arbeit braucht."},"options":[{"id":"0","text":"Arbeitszeiten"},{"id":"1","text":"Arbeitsmittel"},{"id":"2","text":"Arbeitsstellen"},{"id":"3","text":"Arbeitswege"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Arbeitsmittel are tools or equipment used to do a job.","de":"Arbeitsmittel sind Werkzeuge und Geräte, die für eine Tätigkeit eingesetzt werden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Reparatur erhält der Techniker Werkzeug und Messgeräte. Das sind seine Arbeitsmittel.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/nouns.jsonl:L133 (85a1029959b9c7374cec53128af41b3b3033889eb819a698c78533a838e3a613), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
