INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000250021','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000250021","revision":1,"targetId":"80000000-0000-4000-8000-000000002502","prompt":"Die Firma stellt allen Beschäftigten die für ihre Aufgaben nötigen Laptops bereit. Diese gehören zu den ___.","instruction":{"en":"Choose the collective term for the equipment used to do the work, rather than the place where it is installed.","de":"Wähle den Sammelbegriff für die zur Arbeit verwendeten Geräte, nicht für den Ort, an dem sie aufgestellt sind."},"hint":{"en":"These are objects needed to carry out the task.","de":"Gemeint sind Gegenstände, die man für die Arbeit braucht."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Arbeitsplätzen"},{"id":"1","text":"Arbeitsverträgen"},{"id":"2","text":"Arbeitsmitteln"},{"id":"3","text":"Arbeitszeiten"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Arbeitsmittel are tools or equipment used to do a job.","de":"Arbeitsmittel sind Werkzeuge und Geräte, die für eine Tätigkeit eingesetzt werden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma stellt allen Beschäftigten die für ihre Aufgaben nötigen Laptops bereit. Diese gehören zu den Arbeitsmitteln.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/nouns.jsonl:L133 (85a1029959b9c7374cec53128af41b3b3033889eb819a698c78533a838e3a613), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unre