INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000250110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000250110","revision":1,"targetId":"80000000-0000-4000-8000-000000002511","prompt":"Wegen einer Erkrankung kann die Mitarbeiterin ihre Tätigkeit vorübergehend nicht ausüben. Der Arzt bestätigt ihre ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The reason for not working is a health condition, not unemployment.","de":"Der Grund ist gesundheitlich und nicht die Suche nach einer Stelle."},"options":[{"id":"0","text":"Arbeitslosigkeit"},{"id":"1","text":"Arbeitsteilung"},{"id":"2","text":"Arbeitsunfähigkeit"},{"id":"3","text":"Arbeitsweise"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Arbeitsunfähigkeit means inability to work because of illness or health limitations.","de":"Arbeitsunfähigkeit bedeutet, dass jemand aus gesundheitlichen Gründen nicht arbeiten kann."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen einer Erkrankung kann die Mitarbeiterin ihre Tätigkeit vorübergehend nicht ausüben. Der Arzt bestätigt ihre Arbeitsunfähigkeit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/nouns.jsonl:L143 (36e3b27668644d5208c1c541269ed694aab07223f61aa330459a04155cde3a06), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
