INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270090","revision":1,"targetId":"80000000-0000-4000-8000-000000002709","prompt":"Es könnte morgen regnen. Nimm ___ einen Schirm mit.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The outcome is uncertain.","de":"Das Ereignis ist möglich, aber nicht garantiert."},"options":[{"id":"0","text":"sicher"},{"id":"1","text":"eventuell"},{"id":"2","text":"niemals"},{"id":"3","text":"gestern"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"eventuell means possibly or perhaps, not definitely.","de":"eventuell bedeutet möglicherweise, nicht sicher."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Es könnte morgen regnen. Nimm eventuell einen Schirm mit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L146 (2fb3d02a75a5c338d65e0c85668dad50f5380b0679c5f5beacd2c94d6b641c9d), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
