INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270120","revision":1,"targetId":"80000000-0000-4000-8000-000000002712","prompt":"Im Vertrag steht ausdrücklich, dass die Daten nicht weitergegeben werden dürfen. Das ist ___ geregelt.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The requirement is directly stated, not implied.","de":"Die Vorgabe wird ausdrücklich genannt."},"options":[{"id":"0","text":"ungefähr"},{"id":"1","text":"explizit"},{"id":"2","text":"zufällig"},{"id":"3","text":"unbewusst"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"explizit means stated directly and explicitly.","de":"explizit bedeutet ausdrücklich und nicht bloß angedeutet."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Vertrag steht ausdrücklich, dass die Daten nicht weitergegeben werden dürfen. Das ist explizit geregelt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L149 (f3e655575287a3f71cfe7f0249cf2675fdf74d0793b6fc298d737442d184ed9d), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
