INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270121","revision":1,"targetId":"80000000-0000-4000-8000-000000002712","prompt":"Die Leiterin hat ausdrücklich gesagt, dass keine Fotos gemacht werden dürfen. Sie hat es ___ formuliert.","instruction":{"en":"Choose the word describing directly stated rather than implied wording, not whether the remark was incidental or intentional.","de":"Wähle das Wort für eine ausdrücklich genannte statt nur angedeutete Aussage, nicht dafür, ob die Bemerkung beiläufig oder absichtlich war."},"hint":{"en":"The requirement is directly stated, not implied.","de":"Die Vorgabe wird ausdrücklich genannt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"indirekt"},{"id":"1","text":"beiläufig"},{"id":"2","text":"explizit"},{"id":"3","text":"versehentlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"explizit means stated directly and explicitly.","de":"explizit bedeutet ausdrücklich und nicht bloß angedeutet."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Leiterin hat ausdrücklich gesagt, dass keine Fotos gemacht werden dürfen. Sie hat es explizit formuliert.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L149 (f3e655575287a3f71cfe7f0249cf2675fdf74d0793b6fc298d737442d184ed9d), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','