INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270130','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270130","revision":1,"targetId":"80000000-0000-4000-8000-000000002713","prompt":"Die Temperaturen lagen weit über dem üblichen Bereich. Es war ___ heiß.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The degree is far beyond ordinary levels.","de":"Das Ausmaß liegt deutlich über dem Üblichen."},"options":[{"id":"0","text":"mäßig"},{"id":"1","text":"angenehm"},{"id":"2","text":"extrem"},{"id":"3","text":"kühl"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"extrem means very intense or far beyond normal levels.","de":"extrem bedeutet außergewöhnlich stark oder weit außerhalb des Üblichen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Temperaturen lagen weit über dem üblichen Bereich. Es war extrem heiß.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L150 (f4c1f5fbd98f38687649b47ff61ea73a8a57667bf1b3754ae656feebc1ddc8b9), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
