INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270140','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270140","revision":1,"targetId":"80000000-0000-4000-8000-000000002714","prompt":"Beide Mannschaften hielten sich an die Regeln und respektierten den Gegner. Das Spiel war ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Rules are respected and people have equal chances.","de":"Die Regeln gelten für alle und Chancen sind gerecht verteilt."},"options":[{"id":"0","text":"unfair"},{"id":"1","text":"regelwidrig"},{"id":"2","text":"fair"},{"id":"3","text":"unzulässig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"fair means just, equitable or following the rules.","de":"fair bedeutet gerecht und regelgerecht."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Beide Mannschaften hielten sich an die Regeln und respektierten den Gegner. Das Spiel war fair.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L151 (a5b5330b7f8df7ac2a96fca7f6aef957179404079521ec2688fc745e96ed3fd1), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
