INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270160','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270160","revision":1,"targetId":"80000000-0000-4000-8000-000000002716","prompt":"Im kleinen Team kennt jeder jeden; der Umgang ist herzlich und persönlich. Die Atmosphäre ist ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"People interact warmly rather than formally.","de":"Die Menschen gehen herzlich und persönlich miteinander um."},"options":[{"id":"0","text":"distanziert"},{"id":"1","text":"förmlich"},{"id":"2","text":"familiär"},{"id":"3","text":"kühl"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"familiär describes a warm, family-like and informal atmosphere.","de":"familiär bedeutet herzlich, persönlich und familienähnlich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im kleinen Team kennt jeder jeden; der Umgang ist herzlich und persönlich. Die Atmosphäre ist familiär.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L154 (e2cb99c372dcece3608d6593724f69c1c77ae676b394a10235f8afb01e3b8da1), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
