INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270170","revision":1,"targetId":"80000000-0000-4000-8000-000000002717","prompt":"Jedes Bild enthält rote, gelbe und blaue Flächen. Die Bilder sind ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The image includes multiple colors.","de":"Das Bild enthält verschiedene Farben."},"options":[{"id":"0","text":"farblos"},{"id":"1","text":"einfarbig"},{"id":"2","text":"farbig"},{"id":"3","text":"durchsichtig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"farbig means colored or in color.","de":"farbig bedeutet mit Farben gestaltet."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Jedes Bild enthält rote, gelbe und blaue Flächen. Die Bilder sind farbig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L156 (4459833cefc6f10bc7a0886e01f23ac84d34655b8d2bd56d2b5695fb37e2f530), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
