INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270190','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270190","revision":1,"targetId":"80000000-0000-4000-8000-000000002719","prompt":"Die Berechnung enthält mehrere falsche Zahlen. Sie ist ___.","instruction":{"en":"Choose the expression that completes the German sentence accurately.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The result is incorrect or the device malfunctions.","de":"Das Ergebnis enthält Fehler oder das Gerät funktioniert nicht richtig."},"options":[{"id":"0","text":"korrekt"},{"id":"1","text":"fehlerfrei"},{"id":"2","text":"fehlerhaft"},{"id":"3","text":"präzise"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"fehlerhaft means faulty or containing errors.","de":"fehlerhaft bedeutet mit Fehlern oder Mängeln."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Berechnung enthält mehrere falsche Zahlen. Sie ist fehlerhaft.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L159 (7b626985a4414a853d1c1a2305dc7805ac6e30db484beecb7573a623af9ead47), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
