INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000270191','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000270191","revision":1,"targetId":"80000000-0000-4000-8000-000000002719","prompt":"Der Sensor liefert wiederholt falsche Werte. Er ist ___.","instruction":{"en":"Choose the word describing the presence of errors in the readings, rather than their repeatability or the physical condition of the sensor.","de":"Wähle das Wort dafür, dass die Messwerte Fehler enthalten, nicht für ihre Wiederholbarkeit oder den Zustand des Sensors."},"hint":{"en":"The result is incorrect or the device malfunctions.","de":"Das Ergebnis enthält Fehler oder das Gerät funktioniert nicht richtig."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"fehlerhaft"},{"id":"1","text":"fehlerfrei"},{"id":"2","text":"korrekt"},{"id":"3","text":"richtig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"fehlerhaft means faulty or containing errors.","de":"fehlerhaft bedeutet mit Fehlern oder Mängeln."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Sensor liefert wiederholt falsche Werte. Er ist fehlerhaft.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises from pinned apps/web/data/pos/adjectives.jsonl:L159 (7b626985a4414a853d1c1a2305dc7805ac6e30db484beecb7573a623af9ead47), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
