INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280000","revision":1,"targetId":"80000000-0000-4000-8000-000000002800","prompt":"Die Filiale darf keine eigenen Preisregeln festlegen. Sie ist der Zentrale organisatorisch ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Look for which unit has decision-making authority.","de":"Achte darauf, welche Einheit die Entscheidungen trifft."},"options":[{"id":"0","text":"gleichgestellt"},{"id":"1","text":"untergeordnet"},{"id":"2","text":"übergeordnet"},{"id":"3","text":"unabhängig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"jemandem untergeordnet sein means being subordinate to someone or a unit.","de":"jemandem untergeordnet sein bedeutet, einer Person oder Stelle unterstellt zu sein."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Filiale darf keine eigenen Preisregeln festlegen. Sie ist der Zentrale organisatorisch untergeordnet.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L170 (b01960bf531324634b004799b6f6ee804ee03df68269a734493e8a415f0847f4), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
