INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280030','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280030","revision":1,"targetId":"80000000-0000-4000-8000-000000002803","prompt":"Die Werkstatt kann die Reparatur selbst erledigen, denn sie ___ über die nötigen Ersatzteile.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The context describes resources already available, not a discussion.","de":"Es geht um vorhandene Mittel, nicht um eine Diskussion."},"options":[{"id":"0","text":"verhandelt"},{"id":"1","text":"klagt"},{"id":"2","text":"verfügt"},{"id":"3","text":"berichtet"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"über etwas verfügen expresses possession or availability of a resource.","de":"Über etwas verfügen bedeutet, dass eine Ressource vorhanden und nutzbar ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Werkstatt kann die Reparatur selbst erledigen, denn sie verfügt über die nötigen Ersatzteile.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L174 (5408cf31a0683031105440e01aa9b90d5f4520255fe634bc5a4c3b6e5b858a89), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
