INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280050','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280050","revision":1,"targetId":"80000000-0000-4000-8000-000000002805","prompt":"Nora bedient die Maschine seit Jahren ohne Anleitung. Sie ist mit ihr bestens ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person knows how to use or follow something.","de":"Die Person kennt die Anwendung oder Regeln."},"options":[{"id":"0","text":"zufrieden"},{"id":"1","text":"vertraut"},{"id":"2","text":"einverstanden"},{"id":"3","text":"beschäftigt"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Mit etwas vertraut sein means to know it well, not necessarily to like it.","de":"Mit etwas vertraut sein bedeutet, etwas gut zu kennen, nicht unbedingt es zu mögen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nora bedient die Maschine seit Jahren ohne Anleitung. Sie ist mit ihr bestens vertraut.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L176 (6d26242ab10bd69f8f8bf0a4deb54d5063c7874936c033da941f17fb14c1f0d9), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
