INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280061','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280061","revision":1,"targetId":"80000000-0000-4000-8000-000000002806","prompt":"Für Einzelheiten zu den Prüfungsregeln ___ die E-Mail auf die offizielle Webseite.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"A person or text directs attention to another source.","de":"Eine Person oder ein Text weist auf eine andere Quelle hin."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"reagiert"},{"id":"1","text":"verweist"},{"id":"2","text":"hofft"},{"id":"3","text":"verzichtet"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Auf etwas verweisen means to point to or cite a source.","de":"Auf etwas verweisen bedeutet, auf eine Quelle hinzuweisen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für Einzelheiten zu den Prüfungsregeln verweist die E-Mail auf die offizielle Webseite.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L177 (7d568454f1b97d3858dde176fa997952378fa88792971c63d7e142e0f1ec8b15), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
