INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280070","revision":1,"targetId":"80000000-0000-4000-8000-000000002807","prompt":"Mira erklärt Tom Spanisch, und Tom erklärt Mira Deutsch. Beide lernen ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Each person learns something from the other.","de":"Jede Person lernt etwas von der anderen."},"options":[{"id":"0","text":"nebeneinander"},{"id":"1","text":"voneinander"},{"id":"2","text":"gegeneinander"},{"id":"3","text":"aneinander"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"voneinander means from each other, emphasizing reciprocal exchange.","de":"Voneinander bedeutet, dass beide Seiten etwas von der jeweils anderen übernehmen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mira erklärt Tom Spanisch, und Tom erklärt Mira Deutsch. Beide lernen voneinander.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L179 (76516755c011dfb4ab906f90bcafca1e6308d4a9fb531f8399eb92c86ba0baff), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
