INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280080','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280080","revision":1,"targetId":"80000000-0000-4000-8000-000000002808","prompt":"Die Wanderführerin führt die Gruppe an; alle anderen folgen ihr. Sie geht der Gruppe ein Stück ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"One person moves in front and the others follow.","de":"Eine Person geht vorne, die anderen folgen."},"options":[{"id":"0","text":"hinterher"},{"id":"1","text":"entgegen"},{"id":"2","text":"voraus"},{"id":"3","text":"vorbei"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"vorausgehen means to go ahead, not behind or toward the group.","de":"Vorausgehen bedeutet, vor den anderen zu gehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Wanderführerin führt die Gruppe an; alle anderen folgen ihr. Sie geht der Gruppe ein Stück voraus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L180 (d4ba4def815aa64a3efe61444a74c74d96026c67bda2b83eafb0e588b4b287cc), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
