INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280091","revision":1,"targetId":"80000000-0000-4000-8000-000000002809","prompt":"Die Sitzung ist gerade zu Ende gegangen. ___ wurde noch über den Haushalt abgestimmt.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The event happened just a little earlier.","de":"Das Ereignis fand erst vor kurzer Zeit statt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Übermorgen"},{"id":"1","text":"Vorhin"},{"id":"2","text":"Damals"},{"id":"3","text":"Künftig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"vorhin means earlier today, usually a short time ago.","de":"Vorhin bedeutet vor kurzer Zeit, meist am selben Tag."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Sitzung ist gerade zu Ende gegangen. Vorhin wurde noch über den Haushalt abgestimmt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L184 (3b66ce49cb7b27941939a029c5983794513250bab59c4ce7032e0e1164624b8f), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
