INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280110","revision":1,"targetId":"80000000-0000-4000-8000-000000002811","prompt":"Die Firma hat den Vertrag nicht gekündigt. Sie wird den Dienst ___ anbieten.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The activity is not ending or starting for the first time.","de":"Die Tätigkeit endet nicht und beginnt nicht zum ersten Mal."},"options":[{"id":"0","text":"erstmals"},{"id":"1","text":"weiterhin"},{"id":"2","text":"niemals"},{"id":"3","text":"nicht mehr"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Here weiterhin means that an existing activity continues. In other contexts it can also mean furthermore.","de":"Weiterhin drückt hier die Fortsetzung einer bestehenden Tätigkeit aus. In anderen Zusammenhängen kann es auch außerdem bedeuten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma hat den Vertrag nicht gekündigt. Sie wird den Dienst weiterhin anbieten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L192 (443edd3959fe0560a3b1e9adbc73bb4a73f5f398f1c1d3ae1fd9f850ffb44306), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
