INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280120","revision":1,"targetId":"80000000-0000-4000-8000-000000002812","prompt":"Der Grund, ___ das Konzert abgesagt wurde, war ein Stromausfall.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence introduces or asks for a cause.","de":"Der Satz nennt oder erfragt einen Grund."},"options":[{"id":"0","text":"bevor"},{"id":"1","text":"obwohl"},{"id":"2","text":"weshalb"},{"id":"3","text":"sobald"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"weshalb means why or for which reason; it introduces a causal question or relative clause.","de":"Weshalb bedeutet warum oder aus welchem Grund."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Grund, weshalb das Konzert abgesagt wurde, war ein Stromausfall.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L194 (ca28c52eb2eebaea04c8b03d6713ace062bfd88aa8d0c0166d3583fdd1838921), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
