INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280121","revision":1,"targetId":"80000000-0000-4000-8000-000000002812","prompt":"Die Behörde erklärt, ___ die Straße gesperrt wurde: Es gab einen Rohrbruch.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence introduces or asks for a cause.","de":"Der Satz nennt oder erfragt einen Grund."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"wo"},{"id":"1","text":"weshalb"},{"id":"2","text":"wann"},{"id":"3","text":"wie lange"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"weshalb means why or for which reason; it introduces a causal question or relative clause.","de":"Weshalb bedeutet warum oder aus welchem Grund."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Behörde erklärt, weshalb die Straße gesperrt wurde: Es gab einen Rohrbruch.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L194 (ca28c52eb2eebaea04c8b03d6713ace062bfd88aa8d0c0166d3583fdd1838921), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
