INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280131','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280131","revision":1,"targetId":"80000000-0000-4000-8000-000000002813","prompt":"Die Rechnung enthält eine unerwartete Zusatzgebühr. ___ müssen wir mehr zahlen? Wir fragen nach dem Grund.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The speaker wants an explanation for a surprising situation.","de":"Die Person möchte den Grund für eine unerwartete Situation wissen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Wohin"},{"id":"1","text":"Wieso"},{"id":"2","text":"Seit wann"},{"id":"3","text":"Wie viele"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"wieso is a common conversational equivalent of warum.","de":"Wieso ist ein häufiges umgangssprachliches Fragewort für warum."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Rechnung enthält eine unerwartete Zusatzgebühr. Wieso müssen wir mehr zahlen? Wir fragen nach dem Grund.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L198 (96d7142537913ba195f5003a13e2d9bc18c92e8c1b00b6e7d3a2df8e3365cdbd), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
