INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280140','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280140","revision":1,"targetId":"80000000-0000-4000-8000-000000002814","prompt":"Für das Darlehen werden ausdrücklich null Prozent Zinsen berechnet. Es ist ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"No interest is charged on the borrowed amount; this alone says nothing about separate fees.","de":"Auf den geliehenen Betrag werden keine Zinsen berechnet; über gesonderte Gebühren sagt das allein nichts aus."},"options":[{"id":"0","text":"verzinst"},{"id":"1","text":"zinslos"},{"id":"2","text":"hochverzinst"},{"id":"3","text":"variabel verzinst"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"zinslos means interest-free, not merely inexpensive or variable-rate.","de":"Zinslos bedeutet ohne Zinsen, nicht nur mit niedrigen Zinsen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für das Darlehen werden ausdrücklich null Prozent Zinsen berechnet. Es ist zinslos.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L200 (837b78285a7ad37dd3fe0c6a4371a8b019077777d3a849d182f5f32d19b83ee0), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
