INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280150","revision":1,"targetId":"80000000-0000-4000-8000-000000002815","prompt":"Der Polizeimeldung ___ wurde die Straße nach zwei Stunden wieder freigegeben.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The phrase identifies where the information comes from.","de":"Die Wortgruppe nennt die Quelle der Information."},"options":[{"id":"0","text":"entlang"},{"id":"1","text":"zufolge"},{"id":"2","text":"zuliebe"},{"id":"3","text":"gegenüber"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"einer Meldung zufolge means according to a report; zufolge normally follows its dative noun phrase.","de":"Einer Meldung zufolge bedeutet laut einer Meldung; zufolge steht hier nach dem Dativ."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Polizeimeldung zufolge wurde die Straße nach zwei Stunden wieder freigegeben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L203 (4bc172e281040d1673bf1067a9e8258659b9b562ecc96916e1502972fef8ef09), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
