INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280160','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280160","revision":1,"targetId":"80000000-0000-4000-8000-000000002816","prompt":"Die Lösung erfüllt zwei Ziele gleichzeitig: Sie spart Energie und ist ___ leiser.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Two things are true at the same time.","de":"Zwei Aussagen gelten gleichzeitig."},"options":[{"id":"0","text":"danach"},{"id":"1","text":"stattdessen"},{"id":"2","text":"zugleich"},{"id":"3","text":"zuvor"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"zugleich means at the same time or also in the same moment.","de":"Zugleich bedeutet gleichzeitig oder außerdem in derselben Situation."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Lösung erfüllt zwei Ziele gleichzeitig: Sie spart Energie und ist zugleich leiser.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L204 (cf856db3c748720a7fc013eb15552b701557d55a59c4b20a0b396b4cb75fb1f3), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
