INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280161','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280161","revision":1,"targetId":"80000000-0000-4000-8000-000000002816","prompt":"Der neue Raum dient als Büro und ___ als Besprechungszimmer.","instruction":{"en":"Choose the word expressing that the room has both functions at the same time, rather than one before or after the other.","de":"Wähle das Wort dafür, dass der Raum beide Funktionen gleichzeitig hat, nicht eine vor oder nach der anderen."},"hint":{"en":"Two things are true at the same time.","de":"Zwei Aussagen gelten gleichzeitig."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"zugleich"},{"id":"1","text":"stattdessen"},{"id":"2","text":"zuvor"},{"id":"3","text":"danach"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"zugleich means at the same time or also in the same moment.","de":"Zugleich bedeutet gleichzeitig oder außerdem in derselben Situation."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Raum dient als Büro und zugleich als Besprechungszimmer.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L204 (cf856db3c748720a7fc013eb15552b701557d55a59c4b20a0b396b4cb75fb1f3), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
