INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000280170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000280170","revision":1,"targetId":"80000000-0000-4000-8000-000000002817","prompt":"Wir können nicht alle zwölf Berichte heute prüfen. Vier müssen wir aber ___ schaffen.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence sets a lower bound, not an upper bound.","de":"Es geht um eine Untergrenze, nicht um eine Obergrenze."},"options":[{"id":"0","text":"höchstens"},{"id":"1","text":"keinesfalls"},{"id":"2","text":"zumindest"},{"id":"3","text":"niemals"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"zumindest means at least; höchstens means at most.","de":"Zumindest bedeutet mindestens; höchstens bedeutet maximal."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wir können nicht alle zwölf Berichte heute prüfen. Vier müssen wir aber zumindest schaffen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing questions based on lexical/grammar facts from pinned apps/web/data/pos/adverbs.jsonl:L206 (97f61ec7ffd8cd6f41aac766c5d9a81802014b27cff7742324bdd0e7315fdb35), 2026-10-28; no inherited examples copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
