INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290000","revision":1,"targetId":"80000000-0000-4000-8000-000000002900","prompt":"Der neue Plan spart jedes Jahr Stromkosten. Das ist ein starkes ___ für seine Einführung.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone gives a reason for or against a proposal.","de":"Jemand nennt einen Grund für oder gegen einen Vorschlag."},"options":[{"id":"0","text":"Gerücht"},{"id":"1","text":"Versprechen"},{"id":"2","text":"Argument"},{"id":"3","text":"Auftrag"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"An Argument is a reason supporting or opposing a position. The English word argument can also mean a quarrel; the German word for that is Streit.","de":"Ein Argument ist ein Grund für oder gegen eine Position. Das englische Wort argument kann auch einen Streit bezeichnen; dafür verwendet man im Deutschen das Wort Streit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der neue Plan spart jedes Jahr Stromkosten. Das ist ein starkes Argument für seine Einführung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L152 (e9a8be00f0db78288949b65807d48f766d71eacbd2bc16340d7d57babbb1b051), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
