INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290071','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290071","revision":1,"targetId":"80000000-0000-4000-8000-000000002907","prompt":"Das Gericht prüft, ob der geflüchteten Familie wegen drohender Verfolgung ___ gewährt werden muss.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"A person seeks protection because returning home is unsafe.","de":"Eine Person sucht Schutz, weil die Rückkehr gefährlich wäre."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Kredit"},{"id":"1","text":"Rabatt"},{"id":"2","text":"Asyl"},{"id":"3","text":"Gehalt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Asyl beantragen means to apply for asylum; Asyl gewähren means to grant it.","de":"Asyl beantragen bedeutet Schutz beantragen; Asyl gewähren bedeutet ihn bewilligen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Gericht prüft, ob der geflüchteten Familie wegen drohender Verfolgung Asyl gewährt werden muss.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L162 (94c0998cfab5d34b858febaef234dfa2b2cf04f3d9fa6d6f42333bad9cfee2fd), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
