INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290081','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290081","revision":1,"targetId":"80000000-0000-4000-8000-000000002908","prompt":"Nachdem er die Treppe hinaufgerannt war, war er völlig außer ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The phrase describes breathing, not looking or walking.","de":"Die Wendung beschreibt das Atmen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Sicht"},{"id":"1","text":"Ruhe"},{"id":"2","text":"Atem"},{"id":"3","text":"Zeit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"den Atem anhalten means to hold one''s breath; außer Atem means out of breath.","de":"Den Atem anhalten bedeutet kurz nicht atmen; außer Atem bedeutet stark außer Puste."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nachdem er die Treppe hinaufgerannt war, war er völlig außer Atem.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L163 (667673502930104a1646aa6c1ef935fd3efbd09fd380454c03ecedfd88e83a5d), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
