INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290090","revision":1,"targetId":"80000000-0000-4000-8000-000000002909","prompt":"Nach dem Streit spricht im Team kaum jemand. Die ___ im Büro ist angespannt.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The context concerns how people feel together.","de":"Es geht darum, wie sich Menschen in einer Situation fühlen."},"options":[{"id":"0","text":"Temperatur"},{"id":"1","text":"Ausstattung"},{"id":"2","text":"Atmosphäre"},{"id":"3","text":"Beleuchtung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Atmosphäre can mean social mood as well as physical atmosphere; here it means mood.","de":"Atmosphäre kann Luftschicht oder Stimmung bedeuten; hier ist die Stimmung gemeint."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach dem Streit spricht im Team kaum jemand. Die Atmosphäre im Büro ist angespannt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L164 (0bab2eea0ccaeb90de7a3572803b3ac3e413ac91ac81b1f8ac3906c3680c5c1a), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
