INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290100","revision":1,"targetId":"80000000-0000-4000-8000-000000002910","prompt":"Der Bericht beginnt mit einer Einleitung, erklärt dann die Methode und endet mit den Ergebnissen. Sein ___ ist klar.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The parts are arranged in a logical order.","de":"Die Teile sind logisch geordnet."},"options":[{"id":"0","text":"Aufbau"},{"id":"1","text":"Abzug"},{"id":"2","text":"Antrag"},{"id":"3","text":"Abstand"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Aufbau here means structure or organization, not physical construction.","de":"Aufbau bedeutet hier Gliederung, nicht das Errichten eines Gegenstands."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Bericht beginnt mit einer Einleitung, erklärt dann die Methode und endet mit den Ergebnissen. Sein Aufbau ist klar.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L165 (044095e7fdf8039cca180b57d3caffd8c39d7d8ec3712afedb4f964901483f95), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
