INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290101","revision":1,"targetId":"80000000-0000-4000-8000-000000002910","prompt":"Für ihren Vortrag plant sie erst das Problem, dann drei Lösungen und schließlich ein Fazit. Dieser ___ hilft dem Publikum.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The parts are arranged in a logical order.","de":"Die Teile sind logisch geordnet."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Auftrag"},{"id":"1","text":"Aufpreis"},{"id":"2","text":"Aufbau"},{"id":"3","text":"Aufenthalt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Aufbau here means structure or organization, not physical construction.","de":"Aufbau bedeutet hier Gliederung, nicht das Errichten eines Gegenstands."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für ihren Vortrag plant sie erst das Problem, dann drei Lösungen und schließlich ein Fazit. Dieser Aufbau hilft dem Publikum.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L165 (044095e7fdf8039cca180b57d3caffd8c39d7d8ec3712afedb4f964901483f95), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
