INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290110","revision":1,"targetId":"80000000-0000-4000-8000-000000002911","prompt":"Nach der Operation blieb er vier Tage in der Klinik. Sein ___ dort verlief ohne Probleme.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The sentence describes time spent somewhere.","de":"Der Satz beschreibt eine Zeit an einem bestimmten Ort."},"options":[{"id":"0","text":"Auftrag"},{"id":"1","text":"Aufenthalt"},{"id":"2","text":"Aufpreis"},{"id":"3","text":"Aufbau"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Aufenthalt means a stay, whether in a hospital, another city or abroad.","de":"Aufenthalt bedeutet die Zeit, die man an einem Ort verbringt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Operation blieb er vier Tage in der Klinik. Sein Aufenthalt dort verlief ohne Probleme.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L166 (ef62c9028d3d91e6498bac4e3b5eb525d8d638684416d0353ce8ac6bfeeff330), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
