INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290111','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290111","revision":1,"targetId":"80000000-0000-4000-8000-000000002911","prompt":"Während ihres zweimonatigen ___ in Wien besuchte sie jeden Samstag ein Museum.","instruction":{"en":"Choose the noun for time spent in a place, rather than an assigned job or a construction project.","de":"Wähle das Nomen für die Zeit, die man an einem Ort verbringt, nicht für einen Arbeitsauftrag oder ein Bauvorhaben."},"hint":{"en":"The sentence describes time spent somewhere.","de":"Der Satz beschreibt eine Zeit an einem bestimmten Ort."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Auftrags"},{"id":"1","text":"Aufbaus"},{"id":"2","text":"Aufenthalts"},{"id":"3","text":"Aufpreises"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Aufenthalt means a stay, whether in a hospital, another city or abroad.","de":"Aufenthalt bedeutet die Zeit, die man an einem Ort verbringt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Während ihres zweimonatigen Aufenthalts in Wien besuchte sie jeden Samstag ein Museum.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L166 (ef62c9028d3d91e6498bac4e3b5eb525d8d638684416d0353ce8ac6bfeeff330), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
