INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290121","revision":1,"targetId":"80000000-0000-4000-8000-000000002912","prompt":"Obwohl die Aufgabe neu und komplex ist, erfasst Karim die Regeln sofort. Seine ___ beeindruckt das Team.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The person understands new material without long explanations.","de":"Die Person versteht Neues ohne lange Erklärungen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Ausdauer"},{"id":"1","text":"Körperkraft"},{"id":"2","text":"Auffassungsgabe"},{"id":"3","text":"Pünktlichkeit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Auffassungsgabe is the ability to comprehend; schnelle Auffassungsgabe is quick comprehension.","de":"Auffassungsgabe ist die Fähigkeit, Neues zu erfassen; schnell bedeutet hier rasches Verstehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl die Aufgabe neu und komplex ist, erfasst Karim die Regeln sofort. Seine Auffassungsgabe beeindruckt das Team.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L167 (e99ca773e0f52b67c85b141249db553bb779336d2591a8b9bc6e078fe80d90fc), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded