INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290130','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290130","revision":1,"targetId":"80000000-0000-4000-8000-000000002913","prompt":"Im Brief steht, dass der offene Betrag bis Freitag bezahlt werden muss. Es ist eine ___ zur Zahlung.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Someone is asked or required to do something.","de":"Jemand soll eine bestimmte Handlung ausführen."},"options":[{"id":"0","text":"Einladung"},{"id":"1","text":"Aufforderung"},{"id":"2","text":"Entschuldigung"},{"id":"3","text":"Bestätigung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Aufforderung asks someone to act; it can be polite or formal and need not be an aggressive demand.","de":"Aufforderung verlangt oder erbittet eine Handlung und ist nicht immer eine scharfe Forderung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Brief steht, dass der offene Betrag bis Freitag bezahlt werden muss. Es ist eine Aufforderung zur Zahlung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L168 (13efa5324f50e1766146b0d738bf94ceb0393334e5c76718b67d5c361a1fcbeb), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
