INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000290180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000290180","revision":1,"targetId":"80000000-0000-4000-8000-000000002918","prompt":"Die Kundin beauftragt eine Tischlerei, einen Schrank nach Maß zu bauen. Sie erteilt einen ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"One party gives another party a concrete job to perform.","de":"Eine Person oder Firma soll eine bestimmte Arbeit erledigen."},"options":[{"id":"0","text":"Rabatt"},{"id":"1","text":"Auftrag"},{"id":"2","text":"Antrag"},{"id":"3","text":"Bericht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Auftrag can mean order, commission or assignment depending on context.","de":"Auftrag kann eine Bestellung, einen Arbeitsauftrag oder eine Beauftragung bezeichnen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kundin beauftragt eine Tischlerei, einen Schrank nach Maß zu bauen. Sie erteilt einen Auftrag.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 low-typing exercises based on pinned apps/web/data/pos/nouns.jsonl:L174 (708e938a734d2c96818d73b25ffab8db63d813a176c737652dd97b76f2ae86f0), 2026-10-28; inherited example sentences not reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
