INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000310070','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000310070","revision":1,"targetId":"80000000-0000-4000-8000-000000003107","prompt":"Der Junge beleidigt die Lehrerin absichtlich. Seine Bemerkung ist ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The remark is deliberately disrespectful.","de":"Die Bemerkung ist eine absichtliche Beleidigung."},"options":[{"id":"0","text":"höflich"},{"id":"1","text":"frech"},{"id":"2","text":"sachlich"},{"id":"3","text":"zurückhaltend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Disrespectful, cheeky or impudent; the word does not by itself establish deliberate intent.","de":"Respektlos, vorlaut oder unverschämt; das Wort allein sagt nicht, ob dies beabsichtigt ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Junge beleidigt die Lehrerin absichtlich. Seine Bemerkung ist frech.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L171 (f264eec4606993251d9f6dbb9722b643e45ca0fc67e33244611688aa0bbc10b3), 2026-10-28; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
