INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000340040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000340040","revision":1,"targetId":"80000000-0000-4000-8000-000000003404","prompt":"Nach drei Stunden im Stau antwortete er auf jede Frage kurz und ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"He responded impatiently after a stressful delay.","de":"Er reagierte ungeduldig und leicht verärgert."},"options":[{"id":"0","text":"gelassen"},{"id":"1","text":"geduldig"},{"id":"2","text":"gereizt"},{"id":"3","text":"freundlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"To describe a person who reacts impatiently or angrily to small things.","de":"Eine Person beschreiben, die auf Kleinigkeiten ungeduldig oder verärgert reagiert."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach drei Stunden im Stau antwortete er auf jede Frage kurz und gereizt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L201 (998d7137b565d3a0d5a03e2331e66c97f9043db480950ad5b5ed7282ff04deaf), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
