INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000340041','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000340041","revision":1,"targetId":"80000000-0000-4000-8000-000000003404","prompt":"Weil sie kaum geschlafen hatte, reagierte die Kollegin ungewöhnlich ___ auf kleine Fehler.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Lack of sleep made her unusually touchy.","de":"Sie war nach der schlaflosen Nacht leicht verärgert."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"entspannt"},{"id":"1","text":"begeistert"},{"id":"2","text":"sachlich"},{"id":"3","text":"gereizt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"To describe a person who reacts impatiently or angrily to small things.","de":"Eine Person beschreiben, die auf Kleinigkeiten ungeduldig oder verärgert reagiert."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Weil sie kaum geschlafen hatte, reagierte die Kollegin ungewöhnlich gereizt auf kleine Fehler.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L201 (998d7137b565d3a0d5a03e2331e66c97f9043db480950ad5b5ed7282ff04deaf), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
