INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000350040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000350040","revision":1,"targetId":"80000000-0000-4000-8000-000000003504","prompt":"Seit der neuen Buslinie kommen mehr Menschen pünktlich zur Arbeit. Das ist eine positive ___ der Änderung.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Improved punctuality is a consequence of the new route.","de":"Die bessere Pünktlichkeit ist eine Folge der neuen Buslinie."},"options":[{"id":"0","text":"Voraussetzung"},{"id":"1","text":"Ursache"},{"id":"2","text":"Auswirkung"},{"id":"3","text":"Absicht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"A consequence caused by a change or event.","de":"Eine Folge, die eine Veränderung oder ein Ereignis verursacht."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Seit der neuen Buslinie kommen mehr Menschen pünktlich zur Arbeit. Das ist eine positive Auswirkung der Änderung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/nouns.jsonl:L212 (15736f49f6021e2b034c81193f127ee79bb6691248fb4c36782a5af103e61f20), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
