INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000350050','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000350050","revision":1,"targetId":"80000000-0000-4000-8000-000000003505","prompt":"Die Firma überweist den Bonus nächste Woche. Die ___ erfolgt am Freitag.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"The money will be disbursed on Friday.","de":"Am Freitag wird das Geld überwiesen."},"options":[{"id":"0","text":"Einladung"},{"id":"1","text":"Auszahlung"},{"id":"2","text":"Anmeldung"},{"id":"3","text":"Ablehnung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"The act of disbursing an amount of money owed.","de":"Die Überweisung oder Übergabe eines geschuldeten Geldbetrags."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma überweist den Bonus nächste Woche. Die Auszahlung erfolgt am Freitag.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/nouns.jsonl:L213 (338b14a8438c4272d873223ac2d499b1682a6f6241cacc4e14290d5dc1846cc8), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
