INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000370031','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000370031","revision":1,"targetId":"80000000-0000-4000-8000-000000003703","prompt":"Sie genießt ruhige Abende mit Lesen und Kochen zu Hause. Ihr Lebensstil ist sehr ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz inhaltlich richtig ergänzt."},"hint":{"en":"Her lifestyle is centred on home activities.","de":"Ihre Freizeit spielt sich hauptsächlich zu Hause ab."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"hektisch"},{"id":"1","text":"häuslich"},{"id":"2","text":"nomadisch"},{"id":"3","text":"öffentlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"To describe a lifestyle centred on the home.","de":"Einen Lebensstil beschreiben, der stark auf das Zuhause ausgerichtet ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie genießt ruhige Abende mit Lesen und Kochen zu Hause. Ihr Lebensstil ist sehr häuslich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L232 (61996f00fd85d36a2d175cae03b89c120274295cfd95bc054c2e0002096490c7), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
