INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000460090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000460090","revision":1,"targetId":"80000000-0000-4000-8000-000000004609","prompt":"Niemand hat die Tür geöffnet, trotzdem steht sie plötzlich offen. Das ist ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"The event is unexplained.","de":"Das Ereignis ist unerklärt."},"options":[{"id":"0","text":"merkwürdig"},{"id":"1","text":"normal"},{"id":"2","text":"erwartbar"},{"id":"3","text":"logisch"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Here ''merkwürdig'' means strange or odd. The event is unexplained.","de":"Hier bedeutet „merkwürdig“: ungewöhnlich und schwer erklärbar. Das Ereignis ist unerklärt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Niemand hat die Tür geöffnet, trotzdem steht sie plötzlich offen. Das ist merkwürdig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L328 (c54379367cb75009a74753e9c4740939a8350570ab4c86afe0064bd09a17a42e), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
