INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000460180','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000460180","revision":1,"targetId":"80000000-0000-4000-8000-000000004618","prompt":"Obwohl sie Angst hatte, betrat die Feuerwehrfrau das brennende Haus, um jemanden zu retten. Sie handelte ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"She acts despite fear to rescue someone.","de":"Sie handelt trotz Angst, um jemanden zu retten."},"options":[{"id":"0","text":"mutig"},{"id":"1","text":"feige"},{"id":"2","text":"gleichgültig"},{"id":"3","text":"rücksichtslos"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Here ''mutig'' means brave despite fear. She acts despite fear to rescue someone.","de":"Hier bedeutet „mutig“: tapfer trotz Angst oder Risiko. Sie handelt trotz Angst, um jemanden zu retten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl sie Angst hatte, betrat die Feuerwehrfrau das brennende Haus, um jemanden zu retten. Sie handelte mutig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L340 (e95f83db6c84fe35b521f757a53f33b47b3641e120f54cf193dcf71a8498f31e), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
