INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000460181','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000460181","revision":1,"targetId":"80000000-0000-4000-8000-000000004618","prompt":"Er kritisierte die ungerechte Entscheidung offen, obwohl er Nachteile befürchtete. Das war ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"He spoke up despite consequences.","de":"Er äußerte Kritik trotz möglicher Nachteile."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"bequem"},{"id":"1","text":"harmlos"},{"id":"2","text":"mutig"},{"id":"3","text":"gleichgültig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Here ''mutig'' means brave despite fear. He spoke up despite consequences.","de":"Hier bedeutet „mutig“: tapfer trotz Angst oder Risiko. Er äußerte Kritik trotz möglicher Nachteile."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Er kritisierte die ungerechte Entscheidung offen, obwohl er Nachteile befürchtete. Das war mutig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L340 (e95f83db6c84fe35b521f757a53f33b47b3641e120f54cf193dcf71a8498f31e), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
