INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000490130','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000490130","revision":1,"targetId":"80000000-0000-4000-8000-000000004913","prompt":"Er las nur die Überschriften und prüfte keine Details. Seine Analyse blieb ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"Only the surface was examined.","de":"Er hat die Einzelheiten nicht geprüft."},"options":[{"id":"0","text":"oberflächlich"},{"id":"1","text":"gründlich"},{"id":"2","text":"sorgfältig"},{"id":"3","text":"umfassend"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Here ''oberflächlich'' means superficial. Only the surface was examined.","de":"Hier bedeutet „oberflächlich“: ohne Tiefe oder gründliche Prüfung. Er hat die Einzelheiten nicht geprüft."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Er las nur die Überschriften und prüfte keine Details. Seine Analyse blieb oberflächlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L365 (d2108e75dea2552639d7916e56b2c228ee7afb3a8e38d1d0003db1f95c2dc344), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
