INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000490131','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000490131","revision":1,"targetId":"80000000-0000-4000-8000-000000004913","prompt":"Sie hörte kaum zu und fragte nicht nach; das Gespräch wirkte ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"The conversation lacked depth.","de":"Das Gespräch ging nicht in die Tiefe."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"tiefgründig"},{"id":"1","text":"intensiv"},{"id":"2","text":"oberflächlich"},{"id":"3","text":"ausführlich"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Here ''oberflächlich'' means superficial. The conversation lacked depth.","de":"Hier bedeutet „oberflächlich“: ohne Tiefe oder gründliche Prüfung. Das Gespräch ging nicht in die Tiefe."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie hörte kaum zu und fragte nicht nach; das Gespräch wirkte oberflächlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L365 (d2108e75dea2552639d7916e56b2c228ee7afb3a8e38d1d0003db1f95c2dc344), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
