INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000490150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000490150","revision":1,"targetId":"80000000-0000-4000-8000-000000004915","prompt":"Auf dem Boden liegen frische Fußspuren; ___ war jemand hier.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"The footprints support an inference.","de":"Die Spuren lassen auf eine Person schließen."},"options":[{"id":"0","text":"Niemals"},{"id":"1","text":"Offenbar"},{"id":"2","text":"Keinesfalls"},{"id":"3","text":"Selten"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Here ''offenbar'' means apparently, as evidence suggests. The footprints support an inference.","de":"Hier bedeutet „offenbar“: wie es den Anschein hat. Die Spuren lassen auf eine Person schließen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf dem Boden liegen frische Fußspuren; Offenbar war jemand hier.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L368 (c2ffacc76293588f278bbbd26c0da9c492791e5b947b609838fb9407ecab496a), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
