INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000490170','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000490170","revision":1,"targetId":"80000000-0000-4000-8000-000000004917","prompt":"Der Park gehört der Stadt und darf von allen genutzt werden; er ist ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"Everyone can use the park.","de":"Alle dürfen den Park nutzen."},"options":[{"id":"0","text":"öffentlich"},{"id":"1","text":"privat"},{"id":"2","text":"gesperrt"},{"id":"3","text":"geheim"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Here ''öffentlich'' means publicly accessible. Everyone can use the park.","de":"Hier bedeutet „öffentlich“: für alle zugänglich. Alle dürfen den Park nutzen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Park gehört der Stadt und darf von allen genutzt werden; er ist öffentlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L370 (71ad667be801f24740cab09168244baaf1c9504c179c26b57fbc459ecc4e06af), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
