INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000490171','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000490171","revision":1,"targetId":"80000000-0000-4000-8000-000000004917","prompt":"Die Sitzung ist nicht nur für Mitglieder, sondern für alle Bürger zugänglich; sie ist ___.","instruction":{"en":"Choose the word or form that best completes the sentence.","de":"Wähle das Wort oder die Form, die den Satz am besten ergänzt."},"hint":{"en":"The meeting is open to all citizens.","de":"Alle Bürger dürfen teilnehmen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"vertraulich"},{"id":"1","text":"intern"},{"id":"2","text":"öffentlich"},{"id":"3","text":"geschlossen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Here ''öffentlich'' means publicly accessible. The meeting is open to all citizens.","de":"Hier bedeutet „öffentlich“: für alle zugänglich. Alle Bürger dürfen teilnehmen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Sitzung ist nicht nur für Mitglieder, sondern für alle Bürger zugänglich; sie ist öffentlich.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L370 (71ad667be801f24740cab09168244baaf1c9504c179c26b57fbc459ecc4e06af), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
