INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000510000','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000510000","revision":1,"targetId":"80000000-0000-4000-8000-000000005100","prompt":"Der Auftragnehmer muss bis Freitag einen Wartungsnachweis ___.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"A required document must be provided, not invented or requested.","de":"Ein geforderter Nachweis muss vorgelegt werden, nicht erfunden oder erfragt."},"options":[{"id":"0","text":"erbringen"},{"id":"1","text":"erfinden"},{"id":"2","text":"erfragen"},{"id":"3","text":"erhitzen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"A required document must be provided, not invented or requested. Here \"erbringen\" expresses provide or deliver a required service or proof.","de":"Ein geforderter Nachweis muss vorgelegt werden, nicht erfunden oder erfragt. Hier passt „erbringen“ im Sinn von „eine vereinbarte Leistung oder einen Nachweis erbringen“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Auftragnehmer muss bis Freitag einen Wartungsnachweis erbringen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercise text based on lexical facts from pinned apps/web/data/pos/verbs.jsonl:L347 (297c5a29bd989f624857efdc1dae12ff2a8ae34f1983490d0c3f31714f0cb753), 2026-10-29. Source examples were not copied; reuse rights remain for human review. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
