INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550040','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550040","revision":1,"targetId":"80000000-0000-4000-8000-000000005504","prompt":"Die Abteilungen sind ___ getrennt; sie arbeiten in verschiedenen Gebäuden.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The separation concerns physical locations.","de":"Die Abteilungen befinden sich an verschiedenen Orten."},"options":[{"id":"0","text":"räumlich"},{"id":"1","text":"zeitlich"},{"id":"2","text":"rechtlich"},{"id":"3","text":"finanziell"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The separation concerns physical locations. Here \"räumlich\" expresses spatial, related to physical space.","de":"Die Abteilungen befinden sich an verschiedenen Orten. „räumlich“ bedeutet hier „räumlich; den Raum betreffend“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Abteilungen sind räumlich getrennt; sie arbeiten in verschiedenen Gebäuden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L403 (75f44de1efa7889f1c11f8c9e04a638e08cf315cfa82d2005c2c17d6e5097c8e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
