INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550090","revision":1,"targetId":"80000000-0000-4000-8000-000000005509","prompt":"Der Käse stammt von einem Hof in der Nähe und ist ein ___ Produkt.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The cheese comes from the surrounding area.","de":"Der Käse wird in der Region hergestellt."},"options":[{"id":"0","text":"importiertes"},{"id":"1","text":"regionales"},{"id":"2","text":"exotisches"},{"id":"3","text":"überseeisches"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"The cheese comes from the surrounding area. Here \"regionales\" expresses from a particular region.","de":"Der Käse wird in der Region hergestellt. „regionales“ bedeutet hier „regional; aus der Umgebung“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Käse stammt von einem Hof in der Nähe und ist ein regionales Produkt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L409 (23c9ebcb33ee5fa0ae93f5c279e106ac5178c14c698fee9f0bdd5765aabb2462), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
