INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550091","revision":1,"targetId":"80000000-0000-4000-8000-000000005509","prompt":"Das Festival zeigt Filme aus der Umgebung und fördert die ___ Kulturszene.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The event supports local culture.","de":"Das Festival fördert Kultur aus der Region."},"slots":[{"id":"word","label":"Ausdruck","options":[{"id":"0","text":"internationale"},{"id":"1","text":"ausländische"},{"id":"2","text":"globale"},{"id":"3","text":"regionale"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"The event supports local culture. Here \"regionale\" expresses from a particular region.","de":"Das Festival fördert Kultur aus der Region. „regionale“ bedeutet hier „regional; aus der Umgebung“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Festival zeigt Filme aus der Umgebung und fördert die regionale Kulturszene.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L409 (23c9ebcb33ee5fa0ae93f5c279e106ac5178c14c698fee9f0bdd5765aabb2462), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
