INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550100","revision":1,"targetId":"80000000-0000-4000-8000-000000005510","prompt":"Die Pfirsiche sind weich und süß; sie sind ___.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The fruit is ready to eat.","de":"Die Früchte sind essreif."},"options":[{"id":"0","text":"reif"},{"id":"1","text":"unreif"},{"id":"2","text":"gefroren"},{"id":"3","text":"hart"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The fruit is ready to eat. Here \"reif\" expresses ripe or ready.","de":"Die Früchte sind essreif. „reif“ bedeutet hier „reif; erntereif oder bereit“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Pfirsiche sind weich und süß; sie sind reif.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L411 (85ce6f67ed5d7d1a4c100c43d8ef78a8ba6effdc5184ad106d9a10bcef77de12), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
