INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550101","revision":1,"targetId":"80000000-0000-4000-8000-000000005510","prompt":"Nach vielen Gesprächen ist die Zeit ___ für eine Entscheidung.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The moment is right to decide.","de":"Jetzt ist der passende Zeitpunkt für eine Entscheidung."},"slots":[{"id":"word","label":"Ausdruck","options":[{"id":"0","text":"roh"},{"id":"1","text":"rutschig"},{"id":"2","text":"reif"},{"id":"3","text":"salzig"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"The moment is right to decide. Here \"reif\" expresses ripe or ready.","de":"Jetzt ist der passende Zeitpunkt für eine Entscheidung. „reif“ bedeutet hier „reif; erntereif oder bereit“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach vielen Gesprächen ist die Zeit reif für eine Entscheidung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L411 (85ce6f67ed5d7d1a4c100c43d8ef78a8ba6effdc5184ad106d9a10bcef77de12), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
