INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550110','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550110","revision":1,"targetId":"80000000-0000-4000-8000-000000005511","prompt":"Im Vergleich zu anderen Geräten ist dieses Modell ___ günstig.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The price is judged against other models.","de":"Der Preis wird mit anderen Geräten verglichen."},"options":[{"id":"0","text":"absolut"},{"id":"1","text":"relativ"},{"id":"2","text":"vollständig"},{"id":"3","text":"grundsätzlich"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"The price is judged against other models. Here \"relativ\" expresses relative to a comparison.","de":"Der Preis wird mit anderen Geräten verglichen. „relativ“ bedeutet hier „relativ; im Vergleich“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Vergleich zu anderen Geräten ist dieses Modell relativ günstig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L412 (77b0fa65fdf6f75860a55b2576b1311c4c6cd8edb9e61da6fdadcfe5f110ef46), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
