INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550111','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550111","revision":1,"targetId":"80000000-0000-4000-8000-000000005511","prompt":"Die Wartezeit war ___ kurz, wenn man die vielen Besucher berücksichtigt.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The judgment depends on the number of visitors.","de":"Die Wartezeit ist im Verhältnis zur Besucherzahl kurz."},"slots":[{"id":"word","label":"Ausdruck","options":[{"id":"0","text":"endlos"},{"id":"1","text":"völlig"},{"id":"2","text":"unendlich"},{"id":"3","text":"relativ"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"The judgment depends on the number of visitors. Here \"relativ\" expresses relative to a comparison.","de":"Die Wartezeit ist im Verhältnis zur Besucherzahl kurz. „relativ“ bedeutet hier „relativ; im Vergleich“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Wartezeit war relativ kurz, wenn man die vielen Besucher berücksichtigt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L412 (77b0fa65fdf6f75860a55b2576b1311c4c6cd8edb9e61da6fdadcfe5f110ef46), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
