INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550120","revision":1,"targetId":"80000000-0000-4000-8000-000000005512","prompt":"Für die Umfrage wurden Menschen verschiedener Altersgruppen und Regionen ausgewählt, damit die Stichprobe ___ ist.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The sample should reflect the wider population.","de":"Die Stichprobe soll die Bevölkerung angemessen abbilden."},"options":[{"id":"0","text":"repräsentativ"},{"id":"1","text":"einseitig"},{"id":"2","text":"verzerrt"},{"id":"3","text":"unvollständig"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The sample should reflect the wider population. Here \"repräsentativ\" expresses representative of a wider group.","de":"Die Stichprobe soll die Bevölkerung angemessen abbilden. „repräsentativ“ bedeutet hier „repräsentativ; die Gesamtheit widerspiegelnd“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Umfrage wurden Menschen verschiedener Altersgruppen und Regionen ausgewählt, damit die Stichprobe repräsentativ ist.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L413 (09b8b4da77f14653788179298f29dbe1c47215d40f55884df212c07db6f1a187), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
