INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000550121','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000550121","revision":1,"targetId":"80000000-0000-4000-8000-000000005512","prompt":"Die Ergebnisse sollen für die gesamte Bevölkerung gelten; deshalb braucht man eine ___ Auswahl der Befragten.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"The respondents must reflect the population.","de":"Die Befragten sollen die Gesamtheit widerspiegeln."},"slots":[{"id":"word","label":"Ausdruck","options":[{"id":"0","text":"einseitige"},{"id":"1","text":"verzerrte"},{"id":"2","text":"repräsentative"},{"id":"3","text":"willkürliche"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"The respondents must reflect the population. Here \"repräsentative\" expresses representative of a wider group.","de":"Die Befragten sollen die Gesamtheit widerspiegeln. „repräsentative“ bedeutet hier „repräsentativ; die Gesamtheit widerspiegelnd“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Ergebnisse sollen für die gesamte Bevölkerung gelten; deshalb braucht man eine repräsentative Auswahl der Befragten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical facts from pinned apps/web/data/pos/adjectives.jsonl:L413 (09b8b4da77f14653788179298f29dbe1c47215d40f55884df212c07db6f1a187), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
