INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000670011','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000670011","revision":1,"targetId":"80000000-0000-4000-8000-000000006701","prompt":"Sie hat noch keine der beiden Wohnungen gewählt und ist weiterhin ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz am besten ergänzt."},"hint":{"en":"She has not made a choice.","de":"Sie hat sich noch nicht entschieden."},"slots":[{"id":"word","label":"Ausdruck","options":[{"id":"0","text":"überzeugt"},{"id":"1","text":"festgelegt"},{"id":"2","text":"unentschieden"},{"id":"3","text":"sicher"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Unentschieden also describes someone who has not decided.","de":"Unentschieden beschreibt auch eine Person, die noch keine Wahl getroffen hat."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie hat noch keine der beiden Wohnungen gewählt und ist weiterhin unentschieden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts from apps/web/data/pos/adjectives.jsonl:L525 (38be6e89d4b431b859dd8903f9bf2e5c57030dd3c2e4d8b6f8c5cb01b15f0750), 2026-10-29. No inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
