INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000690010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000690010","revision":1,"targetId":"80000000-0000-4000-8000-000000006901","prompt":"Wenn die Lampe vom Tisch fällt, kann sie ___.","instruction":{"en":"Choose the expression that best completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz am besten ergänzt."},"hint":{"en":"The lamp itself may break.","de":"Die Lampe kann dabei beschädigt werden."},"options":[{"id":"0","text":"reparieren"},{"id":"1","text":"kaputtgehen"},{"id":"2","text":"kaputtmachen"},{"id":"3","text":"wachsen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Kaputtgehen describes something breaking by itself.","de":"Kaputtgehen beschreibt, dass etwas kaputt wird."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wenn die Lampe vom Tisch fällt, kann sie kaputtgehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts from apps/web/data/pos/verbs.jsonl:L509 (20b9e431a8a012497d50552c6048b70b256d820d60b3837aaece8be1dc9f9564), 2026-10-29. No inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
