INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000720081','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000720081","revision":1,"targetId":"80000000-0000-4000-8000-000000007208","prompt":"Nach der Reise ___ der Koffer versehentlich an einem anderen Flughafen.","instruction":{"en":"Choose the form that best completes the German sentence.","de":"Wähle die Form, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The suitcase ended up at an unintended destination.","de":"Der Koffer kam an einem falschen Zielort an."},"slots":[{"id":"word","label":"Wort oder Form","options":[{"id":"0","text":"wartete"},{"id":"1","text":"blieb"},{"id":"2","text":"landete"},{"id":"3","text":"schlief"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Landete is also used figuratively when something ends up somewhere.","de":"Landete kann auch übertragen bedeuten, dass etwas an einem Ort ankommt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Reise landete der Koffer versehentlich an einem anderen Flughafen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical and grammar facts from pinned apps/web/data/pos/verbs.jsonl:L550 (ef547016168bbeb514e56268c077f595bc323f404270f2d082f95a545d58802e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
