INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000720090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000720090","revision":1,"targetId":"80000000-0000-4000-8000-000000007209","prompt":"Der eintönige Vortrag ___ die Zuhörer, die bald das Interesse verloren.","instruction":{"en":"Choose the form that best completes the German sentence.","de":"Wähle die Form, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The listeners lost interest because it was dull.","de":"Die Zuhörer verloren wegen der Eintönigkeit das Interesse."},"options":[{"id":"0","text":"begeisterte"},{"id":"1","text":"langweilte"},{"id":"2","text":"überzeugte"},{"id":"3","text":"motivierte"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Langweilte is transitive here: the talk made the listeners bored.","de":"Langweilte wird hier transitiv gebraucht: Der Vortrag machte die Zuhörer unaufmerksam."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der eintönige Vortrag langweilte die Zuhörer, die bald das Interesse verloren.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical and grammar facts from pinned apps/web/data/pos/verbs.jsonl:L551 (e36b6f11af68eea50fdda0afe7ad9cf0f12e17487bbb1b5ac7da223e7bd6699e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
