INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000720091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000720091","revision":1,"targetId":"80000000-0000-4000-8000-000000007209","prompt":"Ohne Spielzeug oder Bücher ___ sich die Kinder während der langen Wartezeit.","instruction":{"en":"Choose the form that best completes the German sentence.","de":"Wähle die Form, die den deutschen Satz am besten ergänzt."},"hint":{"en":"They had nothing to do and found the wait dull.","de":"Sie hatten nichts zu tun und fanden das Warten öde."},"slots":[{"id":"word","label":"Wort oder Form","options":[{"id":"0","text":"beeilten"},{"id":"1","text":"trafen"},{"id":"2","text":"langweilten"},{"id":"3","text":"entschuldigten"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Langweilten sich is the reflexive simple-past form for feeling bored.","de":"Langweilten sich ist die reflexive Präteritumform für das Gefühl der Langeweile."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Ohne Spielzeug oder Bücher langweilten sich die Kinder während der langen Wartezeit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical and grammar facts from pinned apps/web/data/pos/verbs.jsonl:L551 (e36b6f11af68eea50fdda0afe7ad9cf0f12e17487bbb1b5ac7da223e7bd6699e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
