INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000720190','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000720190","revision":1,"targetId":"80000000-0000-4000-8000-000000007219","prompt":"Wir müssen um sechs Uhr ___, sonst verpassen wir die Fähre.","instruction":{"en":"Choose the form that best completes the German sentence.","de":"Wähle die Form, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The journey needs to begin at six.","de":"Die Fahrt muss um sechs Uhr beginnen."},"options":[{"id":"0","text":"ankommen"},{"id":"1","text":"losfahren"},{"id":"2","text":"aussteigen"},{"id":"3","text":"umsteigen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Losfahren means to set off, not to arrive or change vehicles.","de":"Losfahren bedeutet, die Fahrt zu beginnen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wir müssen um sechs Uhr losfahren, sonst verpassen wir die Fähre.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical and grammar facts from pinned apps/web/data/pos/verbs.jsonl:L572 (b4db917dfcfa325d7bcc16890166f90da6a8ab5d34e7b3877f6acc6b7ced7be4), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
