INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770000","revision":1,"targetId":"80000000-0000-4000-8000-000000007700","prompt":"Die Straße ist nur in einer Fahrtrichtung freigegeben. Es handelt sich um eine ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Traffic is permitted in only one direction.","de":"Der Verkehr darf nur in eine Richtung fahren."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Sackgasse"},{"id":"1","text":"Einbahnstraße"},{"id":"2","text":"Bundesstraße"},{"id":"3","text":"Spielstraße"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Einbahnstraße means one-way street. Traffic is permitted in only one direction.","de":"Einbahnstraße bedeutet Straße mit nur einer erlaubten Fahrtrichtung. Der Verkehr darf nur in eine Richtung fahren."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Straße ist nur in einer Fahrtrichtung freigegeben. Es handelt sich um eine Einbahnstraße.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L578 (d0daf00386f5e4651e9693140a9b4935a74a969492178f6b5383b20dae8def60), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
