INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770010','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770010","revision":1,"targetId":"80000000-0000-4000-8000-000000007701","prompt":"Die Schrankfront ist bündig mit der Wand, weil der ___ genau in die Nische eingebaut wurde.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The piece of furniture is permanently fitted into a recess.","de":"Das Möbelstück ist fest in eine Wandnische eingepasst."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Einbauschrank"},{"id":"1","text":"Schreibtisch"},{"id":"2","text":"Nachttisch"},{"id":"3","text":"Couchtisch"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Einbauschrank means built-in wardrobe or cabinet. The piece of furniture is permanently fitted into a recess.","de":"Einbauschrank bedeutet fest in eine Nische eingebauter Schrank. Das Möbelstück ist fest in eine Wandnische eingepasst."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Schrankfront ist bündig mit der Wand, weil der Einbauschrank genau in die Nische eingebaut wurde.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L579 (f49274bf5e592fa88e1481c7f4860132d9ae73310d25183c2d63128b146632cc), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excl