INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770040','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770040","revision":1,"targetId":"80000000-0000-4000-8000-000000007704","prompt":"Der Mann hebelte nachts ein fremdes Fenster auf und stahl Schmuck. Er war ein ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"He entered someone else''s property by force to steal.","de":"Er drang gewaltsam in fremde Räume ein, um zu stehlen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Besucher"},{"id":"1","text":"Einbrecher"},{"id":"2","text":"Hausmeister"},{"id":"3","text":"Vermieter"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Einbrecher means burglar (masculine form). He entered someone else''s property by force to steal.","de":"Einbrecher bedeutet Person, die unbefugt einbricht (maskuline Form). Er drang gewaltsam in fremde Räume ein, um zu stehlen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Mann hebelte nachts ein fremdes Fenster auf und stahl Schmuck. Er war ein Einbrecher.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L582 (584b1099340df80bbf67966ad5e697326f114bca85ea44fbbd97459b95c74b08), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
