INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770041','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770041","revision":1,"targetId":"80000000-0000-4000-8000-000000007704","prompt":"Die Polizei nahm den ___ fest, als er durch die aufgebrochene Hintertür mit gestohlenen Laptops das Büro verließ.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The person was caught leaving the scene with stolen items.","de":"Die Person verließ den Tatort mit gestohlenen Gegenständen."},"options":[{"id":"0","text":"Lieferanten"},{"id":"1","text":"Handwerker"},{"id":"2","text":"Einbrecher"},{"id":"3","text":"Mieter"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Einbrecher means burglar (masculine form). The person was caught leaving the scene with stolen items.","de":"Einbrecher bedeutet Person, die unbefugt einbricht (maskuline Form). Die Person verließ den Tatort mit gestohlenen Gegenständen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Polizei nahm den Einbrecher fest, als er durch die aufgebrochene Hintertür mit gestohlenen Laptops das Büro verließ.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L582 (584b1099340df80bbf67966ad5e697326f114bca85ea44fbbd97459b95c74b08), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
