INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770060','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770060","revision":1,"targetId":"80000000-0000-4000-8000-000000007706","prompt":"Die Tür war aufgebrochen worden. Nach dem ___ fehlten mehrere Computer aus dem Büro.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Property disappeared from a locked office after forced entry.","de":"Aus einem verschlossenen Büro wurden Gegenstände gestohlen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Umzug"},{"id":"1","text":"Einkauf"},{"id":"2","text":"Ausflug"},{"id":"3","text":"Einbruch"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"Einbruch means burglary or break-in. Property disappeared from a locked office after forced entry.","de":"Einbruch bedeutet unbefugtes gewaltsames Eindringen. Aus einem verschlossenen Büro wurden Gegenstände gestohlen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Tür war aufgebrochen worden. Nach dem Einbruch fehlten mehrere Computer aus dem Büro.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L584 (667be85d46011ff76f07058e992906510d97227ad93af8fd3c988074401c988f), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
