INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770070','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770070","revision":1,"targetId":"80000000-0000-4000-8000-000000007707","prompt":"Wegen des Produktionsstopps musste die Firma hohe finanzielle ___ hinnehmen.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The shutdown caused financial harm rather than a benefit.","de":"Der Produktionsstopp verursachte finanzielle Nachteile."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Gewinne"},{"id":"1","text":"Zuschüsse"},{"id":"2","text":"Einbußen"},{"id":"3","text":"Prämien"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Einbuße means loss or reduction, often financial. The shutdown caused financial harm rather than a benefit.","de":"Einbuße bedeutet Verlust oder Verringerung, oft finanziell. Der Produktionsstopp verursachte finanzielle Nachteile."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen des Produktionsstopps musste die Firma hohe finanzielle Einbußen hinnehmen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L585 (088c29079cb20a15d2af055b42df519766ee27a405ceaf0b85f36bc19c1f3be4), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
