INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770091','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770091","revision":1,"targetId":"80000000-0000-4000-8000-000000007709","prompt":"Der Lieferwagen versperrte die ___, sodass niemand mit dem Auto auf das Grundstück gelangen konnte.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The blocked route is used to drive onto the property.","de":"Blockiert ist der Weg, auf dem Autos auf das Grundstück gelangen."},"options":[{"id":"0","text":"Ausfahrt"},{"id":"1","text":"Einfahrt"},{"id":"2","text":"Umleitung"},{"id":"3","text":"Haltestelle"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Einfahrt means driveway or vehicle entrance. The blocked route is used to drive onto the property.","de":"Einfahrt bedeutet Zufahrt für Fahrzeuge. Blockiert ist der Weg, auf dem Autos auf das Grundstück gelangen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Lieferwagen versperrte die Einfahrt, sodass niemand mit dem Auto auf das Grundstück gelangen konnte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L587 (560dfb9a42901fcd23e730d8373013fdb16a590a2755b22c136db75c7c8fcff1), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
