INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770101','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770101","revision":1,"targetId":"80000000-0000-4000-8000-000000007710","prompt":"Beim Spaziergang kam ihm ein ___: Er wusste plötzlich, wie das neue Produkt heißen sollte.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"He spontaneously thought of a product name.","de":"Er dachte spontan an einen möglichen Produktnamen."},"options":[{"id":"0","text":"Einfall"},{"id":"1","text":"Einbruch"},{"id":"2","text":"Einzug"},{"id":"3","text":"Eindruck"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Einfall means sudden idea. He spontaneously thought of a product name.","de":"Einfall bedeutet plötzlicher Gedanke oder Idee. Er dachte spontan an einen möglichen Produktnamen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Beim Spaziergang kam ihm ein Einfall: Er wusste plötzlich, wie das neue Produkt heißen sollte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L588 (56c5466c6aaca1e23513687fc50325f98f7c5d59b705305c836b4fe93ffa23f7), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
