INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770110','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770110","revision":1,"targetId":"80000000-0000-4000-8000-000000007711","prompt":"Die Eltern haben großen ___ auf die Entscheidung ihrer Kinder.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Their opinions can affect the children''s decision.","de":"Die Haltung der Eltern kann die Entscheidung verändern."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Einblick"},{"id":"1","text":"Eindruck"},{"id":"2","text":"Einfluss"},{"id":"3","text":"Einfall"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Einfluss means influence or effect. Their opinions can affect the children''s decision.","de":"Einfluss bedeutet Wirkung auf Personen, Vorgänge oder Entscheidungen. Die Haltung der Eltern kann die Entscheidung verändern."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Eltern haben großen Einfluss auf die Entscheidung ihrer Kinder.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L589 (b2ca506a56341c39385650dcf6a1fbec5c0074b9daa10eacff6d1a3743ef1392), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
