INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770120','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770120","revision":1,"targetId":"80000000-0000-4000-8000-000000007712","prompt":"Neue Beschäftigte erhalten vor Arbeitsbeginn eine ___ in die Sicherheitsregeln.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"New staff are being familiarized with the rules.","de":"Neue Beschäftigte lernen die Regeln zunächst kennen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Entlassung"},{"id":"1","text":"Einführung"},{"id":"2","text":"Einladung"},{"id":"3","text":"Entscheidung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Einführung means introduction or implementation of something new. New staff are being familiarized with the rules.","de":"Einführung bedeutet Einweisung oder erstmalige Umsetzung. Neue Beschäftigte lernen die Regeln zunächst kennen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Neue Beschäftigte erhalten vor Arbeitsbeginn eine Einführung in die Sicherheitsregeln.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L590 (65849ea42f1d0173b0f2a901786ee26c4c22cd796f06bb16719e3fd328306ff0), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
