INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770130','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770130","revision":1,"targetId":"80000000-0000-4000-8000-000000007713","prompt":"Der Lieferant hat uns die Ware berechnet. Die Buchhaltung prüft nun die ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"This invoice came into the company from a supplier.","de":"Diese Rechnung ist vom Lieferanten im Unternehmen eingegangen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Eingangsrechnung"},{"id":"1","text":"Ausgangsrechnung"},{"id":"2","text":"Lohnabrechnung"},{"id":"3","text":"Gutschrift"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Eingangsrechnung means invoice received from a supplier. This invoice came into the company from a supplier.","de":"Eingangsrechnung bedeutet Rechnung, die ein Unternehmen von einem Lieferanten erhält. Diese Rechnung ist vom Lieferanten im Unternehmen eingegangen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Lieferant hat uns die Ware berechnet. Die Buchhaltung prüft nun die Eingangsrechnung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L592 (ca2976e50adcd979db372d04b5de22d085ee9321c8ada13ff6efdff209a05bf4), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
