INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000770190','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000770190","revision":1,"targetId":"80000000-0000-4000-8000-000000007719","prompt":"Nach der Reduzierung ihrer Arbeitszeit musste sie eine deutliche ___ verkraften.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Working fewer hours reduced her earnings.","de":"Durch weniger Arbeitsstunden sanken ihre Einnahmen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Gehaltserhöhung"},{"id":"1","text":"Beförderung"},{"id":"2","text":"Einkommenseinbuße"},{"id":"3","text":"Prämienzahlung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Einkommenseinbuße means loss of income. Working fewer hours reduced her earnings.","de":"Einkommenseinbuße bedeutet Verringerung der bisherigen Einnahmen. Durch weniger Arbeitsstunden sanken ihre Einnahmen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Reduzierung ihrer Arbeitszeit musste sie eine deutliche Einkommenseinbuße verkraften.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L599 (68937142e74b63442e378244d20fea99430cca0f27b93ac380b49773e8c80f7b), 2026-10-29. No inherited example text copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
