INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780010','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780010","revision":1,"targetId":"80000000-0000-4000-8000-000000007801","prompt":"Die Bestellung war unvollständig. Der Händler wird die fehlenden Teile kostenlos ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Some ordered items did not arrive in the first shipment.","de":"Ein Teil der bestellten Ware fehlte bei der ersten Lieferung."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"entsorgen"},{"id":"1","text":"abbestellen"},{"id":"2","text":"nachliefern"},{"id":"3","text":"zurückfordern"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"2"}]}],"explanation":{"en":"nachliefern means deliver missing goods later. Some ordered items did not arrive in the first shipment.","de":"nachliefern bedeutet fehlende Waren später zusätzlich liefern. Ein Teil der bestellten Ware fehlte bei der ersten Lieferung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Bestellung war unvollständig. Der Händler wird die fehlenden Teile kostenlos nachliefern.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L606 (7ac051867d519e4b2158f7551d36c8f3b35202cabfb7ac17755d40b3b9b51369), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unr