INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780011','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780011","revision":1,"targetId":"80000000-0000-4000-8000-000000007801","prompt":"Das Ersatzteil war nicht auf Lager. Der Hersteller hat zugesagt, es nächste Woche ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"A promised part will arrive after the original order.","de":"Ein zugesagtes Teil soll erst nach der ursprünglichen Bestellung eintreffen."},"options":[{"id":"0","text":"wegzuwerfen"},{"id":"1","text":"nachzuliefern"},{"id":"2","text":"abzuholen"},{"id":"3","text":"zurückzugeben"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"nachliefern means deliver missing goods later. A promised part will arrive after the original order.","de":"nachliefern bedeutet fehlende Waren später zusätzlich liefern. Ein zugesagtes Teil soll erst nach der ursprünglichen Bestellung eintreffen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Ersatzteil war nicht auf Lager. Der Hersteller hat zugesagt, es nächste Woche nachzuliefern.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L606 (7ac051867d519e4b2158f7551d36c8f3b35202cabfb7ac17755d40b3b9b51369), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
