INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780040','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780040","revision":1,"targetId":"80000000-0000-4000-8000-000000007804","prompt":"Mit der ausführlichen Erklärung konnte ich die Entscheidung endlich ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The explanation made the reasoning understandable.","de":"Die Begründung machte die Entscheidung verständlich."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"durchsetzen"},{"id":"1","text":"nachvollziehen"},{"id":"2","text":"zurückziehen"},{"id":"3","text":"verschweigen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"1"}]}],"explanation":{"en":"nachvollziehen means understand or retrace a reason or process. The explanation made the reasoning understandable.","de":"nachvollziehen bedeutet Gedanken oder Abläufe verstehen und gedanklich verfolgen. Die Begründung machte die Entscheidung verständlich."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mit der ausführlichen Erklärung konnte ich die Entscheidung endlich nachvollziehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L609 (fbbd32c05faf04e0a664d81ebcefea32aeb16ecca1b76469f37bfafb4695e946), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved mate