INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780050','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780050","revision":1,"targetId":"80000000-0000-4000-8000-000000007805","prompt":"Die Bewerberin muss ihre Qualifikation durch Zeugnisse ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Certificates provide documentary evidence.","de":"Zeugnisse dienen als Beleg für eine Qualifikation."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"verheimlichen"},{"id":"1","text":"abschaffen"},{"id":"2","text":"nachweisen"},{"id":"3","text":"verschieben"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"2"}]}],"explanation":{"en":"nachweisen means prove with evidence. Certificates provide documentary evidence.","de":"nachweisen bedeutet durch Belege oder Daten belegen. Zeugnisse dienen als Beleg für eine Qualifikation."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Bewerberin muss ihre Qualifikation durch Zeugnisse nachweisen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L610 (a9e2246738178a8f284c322b94871e2dbfc7295aa3915ff8834e21636f4def35), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
