INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780061','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780061","revision":1,"targetId":"80000000-0000-4000-8000-000000007806","prompt":"Die bisherigen Daten ___, dass die Nachfrage steigt; ein Beweis fehlt noch.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The evidence points in a direction but is not conclusive.","de":"Die Daten deuten auf etwas hin, beweisen es aber noch nicht."},"options":[{"id":"0","text":"beweisen"},{"id":"1","text":"widerlegen"},{"id":"2","text":"legen nahe"},{"id":"3","text":"verschweigen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"nahelegen means recommend or suggest without imposing. The evidence points in a direction but is not conclusive.","de":"nahelegen bedeutet empfehlen oder als wahrscheinlich erscheinen lassen. Die Daten deuten auf etwas hin, beweisen es aber noch nicht."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die bisherigen Daten legen nahe, dass die Nachfrage steigt; ein Beweis fehlt noch.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L611 (3d25f64dc83b5c4e0bb71abd23f2c5d51711bf8b78bec1a2fb5fd5b80d68ba4b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
