INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000780071','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000780071","revision":1,"targetId":"80000000-0000-4000-8000-000000007807","prompt":"Für das Kostüm hat er die beiden Stoffteile sorgfältig ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Two pieces of cloth were joined by stitching.","de":"Zwei Stoffstücke wurden mit Stichen verbunden."},"options":[{"id":"0","text":"geschraubt"},{"id":"1","text":"gegossen"},{"id":"2","text":"gesägt"},{"id":"3","text":"zusammengenäht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"nähen means sew fabric with thread. Two pieces of cloth were joined by stitching.","de":"nähen bedeutet Stoff mit Nadel und Faden verbinden oder reparieren. Zwei Stoffstücke wurden mit Stichen verbunden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für das Kostüm hat er die beiden Stoffteile sorgfältig zusammengenäht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L612 (9262a242f7dac12422837212d485d665cac72326b90f0c12b022000e82265f62), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T12:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved. Direct incremental production authorized; unresolved material defects excluded.','approved');
